#[test]
fn d81_v3_fold_keeps_raw_simulation_inputs_and_rejects_presentation_era_v2() {
    let row = compact_contract::rail_replay::RailHubSimulationState {
        pov_country_id: 7,
        province_id: 42,
        province_owner_country_id: 9,
        // The engine admits exactly two (subtype, route_class) pairs -- (0, 2)
        // and (1, 1) -- per `compact_contract::rail_replay`'s hub-simulation
        // validation and the collector read that produces them. (1, 2) is not a
        // row any capture can carry, so the encoder was right to refuse it.
        subtype: 1,
        route_class: 1,
        node_kind: 5,
        node_flag: 1,
        available_raw: 1_250_000,
        consumed_raw: 375_000,
        foreign_max_raw: 2_000_000,
        foreign_route: true,
        fallback_record: false,
    };
    let payload = compact_contract::rail_replay::encode_payload_with_hub_simulation(
        &[],
        &[row],
        11,
        0,
        0,
        0,
    )
    .unwrap();
    let mut fold = WorldFold::new("d81_v3_raw_simulation");
    fold.fold_rail_replay_state(&payload).unwrap();
    let state = fold.rail_replay_state.as_ref().unwrap();
    assert_eq!(
        state.payload_version,
        compact_contract::rail_replay::PAYLOAD_VERSION_V3
    );
    assert!(state.hub_simulation_complete);
    assert_eq!(state.hub_simulation_rows, vec![row]);

    let hour = raw_for(16_959_360);
    let mut stream = Vec::new();
    push_record(
        &mut stream,
        1,
        hour,
        compact_contract::rail_replay::DOMAIN_ID,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &payload,
    );
    push_record(
        &mut stream,
        2,
        hour,
        compact_contract::COMPACT_DOMAIN_FRAME,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );
    let mut projected = WorldFold::new("d81_v3_projection");
    projected.ingest_stream(&stream);
    let snapshots = projected
        .finish()
        .into_iter()
        .map(|(_, _, bytes)| parse(&bytes))
        .collect::<Vec<_>>();
    let rail = &snapshots[0]["map"]["rail_replay_state_live"];
    assert_eq!(rail["authority"], json!("exact_a729_supply_simulation_tables"));
    assert_eq!(rail["hub_simulation"][0]["pov_country_id"], json!(7));
    assert_eq!(rail["hub_simulation"][0]["available_raw"], json!(1_250_000));
    assert_eq!(rail["viewer_state_captured"], json!(false));
    assert_eq!(rail["derived_visual_frames_captured"], json!(false));
    assert!(rail.get("hub_frames").is_none());

    // A historical v2 presentation-cache payload, built byte-exactly rather
    // than through `encode_payload_with_hub_frames`. That encoder is gated on
    // `HUB_FRAME_V2_ENCODER_PROMOTED`, which is deliberately `false`: the v2
    // cached-frame source is UI-owned and is not a production authority, so the
    // contract retains v2 for DECODING historical evidence only and refuses to
    // mint it. `decode_payload` below is the proof this really is a v2 payload
    // the fold could be handed, not a shape invented for the test.
    let mut legacy = vec![0u8; compact_contract::rail_replay::HEADER_LEN];
    legacy[..4].copy_from_slice(b"RRL1");
    legacy[4..6].copy_from_slice(&compact_contract::rail_replay::PAYLOAD_VERSION_V2.to_le_bytes());
    legacy[6..8]
        .copy_from_slice(&(compact_contract::rail_replay::HEADER_LEN as u16).to_le_bytes());
    legacy[8..10].copy_from_slice(&(compact_contract::rail_replay::ROW_LEN as u16).to_le_bytes());
    legacy[32..36].copy_from_slice(
        &compact_contract::rail_replay::PAYLOAD_FLAG_HUB_FRAMES_COMPLETE.to_le_bytes(),
    );
    let decoded_legacy = compact_contract::rail_replay::decode_payload(&legacy).unwrap();
    assert_eq!(
        decoded_legacy.payload_version,
        compact_contract::rail_replay::PAYLOAD_VERSION_V2
    );
    assert!(decoded_legacy.hub_frames_complete);
    assert!(!decoded_legacy.hub_simulation_complete);
    let error = fold
        .fold_rail_replay_state(&legacy)
        .expect_err("legacy presentation cache must not enter production fold");
    assert_eq!(
        error,
        "rail_replay_state RRL1 rejected: production recorder requires v3 raw supply-simulation authority"
    );
}

#[test]
fn snapshot_spill_never_truncates_a_preexisting_destination() {
    let root = std::env::temp_dir().join(format!(
        "world_fold_create_new_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&root).unwrap();
    let protected = root.join("protected.txt");
    let snapshot_path = root.join("000000000001.snapshot.json");
    let original = b"must not be truncated";
    std::fs::write(&protected, original).unwrap();
    std::fs::hard_link(&protected, &snapshot_path).unwrap();

    let mut snapshot = serde_json::json!({"x": 1});
    let error = serialize_write_hash_snapshot(&snapshot_path, &mut snapshot)
        .expect_err("an existing output name must fail atomically");
    assert_eq!(error.kind(), std::io::ErrorKind::AlreadyExists);
    assert_eq!(std::fs::read(&protected).unwrap(), original);

    std::fs::remove_dir_all(root).unwrap();
}

/// The render-blob preservation pass skips its full-document parse when the
/// `production_render` member cannot be present, and that skip must be decided
/// by the member's ACTUAL presence -- not by anything cheaper that happens to
/// correlate with it.
///
/// The short-circuit exists because the parse is the expensive part: on capture
/// t30 it read 4.44 GB of world JSON across 129 hours (47 s, 12.9% of the whole
/// finalize) and produced zero blobs. A wrong needle, or a short-circuit that
/// fired while the member WAS present, would silently stop emitting render
/// artifacts on exactly the captures that have them -- a data loss no digest
/// check downstream would catch, because the canonical JSON the cache stores is
/// unchanged either way. This asserts both directions on the same helper.
#[test]
fn render_blob_preservation_skips_only_documents_without_the_member() {
    let root = std::env::temp_dir().join(format!(
        "world_fold_render_blob_guard_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));

    // A document with no `production_render` member writes nothing -- and is
    // the case the short-circuit is for.
    let without = root.join("without");
    std::fs::create_dir_all(&without).unwrap();
    let plain = serde_json::to_vec(&json!({
        "schema_version": "1",
        "hour_index": 7,
        "countries": {"GER": {"fuel": 12}},
    }))
    .unwrap();
    preserve_production_render_blobs_from_json(&without, &plain)
        .expect("a document without the member is preserved trivially");
    assert!(
        !without.join("production_render_blobs").exists(),
        "no blob directory may be created for a document that carries no render member"
    );

    // The same helper on a document that DOES carry an inline texture must
    // still write the content-addressed blob. If the short-circuit ever fires
    // here, this is the assertion that fails.
    let with = root.join("with");
    std::fs::create_dir_all(&with).unwrap();
    let encoded = "QUJDRA==";
    let rendered = serde_json::to_vec(&json!({
        "schema_version": "1",
        "hour_index": 7,
        "production_render": {
            "submits": [{
                "authenticated_texture_snapshots": [{
                    "resource": {
                        "subresources": [{
                            "source": {"kind": "inline", "bytes": encoded}
                        }]
                    }
                }]
            }]
        },
    }))
    .unwrap();
    preserve_production_render_blobs_from_json(&with, &rendered)
        .expect("an inline texture must be preserved");
    let digest = snapshot::sha256::Sha256::hex(encoded.as_bytes());
    let blob = with.join("production_render_blobs").join(format!("{digest}.base64"));
    assert!(
        blob.exists(),
        "the inline texture must still land as a content-addressed blob at {}",
        blob.display()
    );
    assert_eq!(std::fs::read(&blob).unwrap(), encoded.as_bytes());

    // The member spelled with a `\u` escape. This is valid JSON whose key a
    // parser decodes to `production_render` while the document contains none of
    // that name's literal bytes, so a scan for the literal alone would skip it
    // and silently drop the blob. Written as raw bytes because `serde_json`
    // would normalize the escape away, which is precisely the point: this is
    // the document an ALTERNATIVE producer can hand this public helper.
    let escaped_dir = root.join("escaped");
    std::fs::create_dir_all(&escaped_dir).unwrap();
    // The leading `p` is spelled `p`. The backslash is pushed by code
    // point so the fixture's escape cannot be silently absorbed by Rust's own
    // string escaping -- an earlier draft of this test lost it exactly that way
    // and asserted nothing.
    let mut escaped = Vec::new();
    escaped.extend_from_slice(br#"{"schema_version":"1","hour_index":7,""#);
    escaped.push(0x5c);
    escaped.extend_from_slice(br#"u0070roduction_render":{"submits":[{"authenticated_texture_snapshots":[{"resource":{"subresources":[{"source":{"kind":"inline","bytes":"WFlaVw=="}}]}}]}]}}"#);
    assert!(
        !String::from_utf8_lossy(&escaped).contains("production_render"),
        "the fixture must not contain the literal name, or it proves nothing"
    );
    preserve_production_render_blobs_from_json(&escaped_dir, &escaped)
        .expect("an escaped member name is still the member");
    let escaped_digest = snapshot::sha256::Sha256::hex(b"WFlaVw==");
    assert!(
        escaped_dir
            .join("production_render_blobs")
            .join(format!("{escaped_digest}.base64"))
            .exists(),
        "a member spelled with a \\u escape must still have its texture preserved"
    );

    std::fs::remove_dir_all(root).unwrap();
}

/// The certified finalize path preserves render blobs from the SAME parse the
/// checkpoint cache makes, and must find exactly what the bytes-taking helper
/// finds.
///
/// This is the path that actually runs on a capture, so a wrong member name, a
/// wrong nesting level, or a string read that returns the escaped body instead
/// of the decoded text would drop render artifacts on every real seal -- and
/// nothing downstream would notice, because the canonical JSON the cache stores
/// is identical either way. Both helpers are driven over the same document and
/// required to produce the same content-addressed blob, so the two cannot drift
/// apart silently.
#[test]
fn canon_render_blob_preservation_matches_the_bytes_path() {
    let root = std::env::temp_dir().join(format!(
        "world_fold_canon_render_blob_{}_{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));

    // Four inline textures, deliberately spread one per level of the nesting --
    // second submit, second packet, second subresource -- so a helper that
    // stopped at the first element of ANY of those three lists would write
    // fewer blobs than this asserts. The first body carries a character
    // `serde_json` escapes, so reading the member as its raw string BODY rather
    // than its decoded text would hash different bytes and fail here too.
    let encoded = "QUJDRA==\n\"tail\"";
    let second_subresource = "U0VDT05E";
    let second_packet = "UEFDS0VU";
    let second_submit = "U1VCTUlU";
    let rendered = serde_json::to_vec(&json!({
        "date": "1936.01.01",
        "hour_index": 7,
        "production_render": {
            "submits": [
                {
                    "authenticated_texture_snapshots": [
                        {
                            "resource": {
                                "subresources": [
                                    {"source": {"kind": "external", "bytes": "SKIPPED"}},
                                    {"source": {"kind": "inline", "bytes": encoded}},
                                    {"source": {"kind": "inline", "bytes": second_subresource}},
                                ]
                            }
                        },
                        {
                            "resource": {
                                "subresources": [
                                    {"source": {"kind": "inline", "bytes": second_packet}},
                                ]
                            }
                        },
                    ]
                },
                {
                    "authenticated_texture_snapshots": [{
                        "resource": {
                            "subresources": [
                                {"source": {"kind": "inline", "bytes": second_submit}},
                            ]
                        }
                    }]
                },
            ]
        },
        "schema_version": "1",
    }))
    .unwrap();
    assert!(
        String::from_utf8_lossy(&rendered).contains("\\n"),
        "the fixture must carry an escaped character, or it proves nothing"
    );
    let digest = snapshot::sha256::Sha256::hex(encoded.as_bytes());

    let from_bytes = root.join("bytes");
    std::fs::create_dir_all(&from_bytes).unwrap();
    preserve_production_render_blobs_from_json(&from_bytes, &rendered)
        .expect("an inline texture must be preserved from bytes");

    let from_canon = root.join("canon");
    std::fs::create_dir_all(&from_canon).unwrap();
    let parsed = snapshot::canon_value::CanonValue::parse(&rendered)
        .expect("the fixture is canonical world JSON");
    preserve_production_render_blobs_from_canon(&from_canon, &parsed)
        .expect("an inline texture must be preserved from the shared parse");

    let name = format!("{digest}.base64");
    let bytes_blob = from_bytes.join("production_render_blobs").join(&name);
    let canon_blob = from_canon.join("production_render_blobs").join(&name);
    assert!(
        canon_blob.exists(),
        "the shared-parse path must write the same content-addressed blob at {}",
        canon_blob.display()
    );
    assert_eq!(
        std::fs::read(&canon_blob).unwrap(),
        encoded.as_bytes(),
        "the shared-parse path must write the DECODED string, not its escaped body"
    );
    for (label, body) in [
        ("second subresource", second_subresource),
        ("second packet", second_packet),
        ("second submit", second_submit),
    ] {
        let digest = snapshot::sha256::Sha256::hex(body.as_bytes());
        assert!(
            from_canon
                .join("production_render_blobs")
                .join(format!("{digest}.base64"))
                .exists(),
            "the shared-parse path stopped before the {label} texture"
        );
    }
    assert_eq!(
        std::fs::read_dir(from_canon.join("production_render_blobs"))
            .unwrap()
            .count(),
        4,
        "exactly the four inline textures, and not the external one"
    );
    assert_eq!(
        std::fs::read_dir(from_canon.join("production_render_blobs"))
            .unwrap()
            .count(),
        std::fs::read_dir(from_bytes.join("production_render_blobs"))
            .unwrap()
            .count(),
        "the two paths must select the same set of subresources"
    );
    assert!(bytes_blob.exists(), "fixture sanity: the bytes path wrote it too");

    // A document with no `production_render` member creates no directory on the
    // shared-parse path either.
    let plain = serde_json::to_vec(&json!({
        "date": "1936.01.01",
        "hour_index": 7,
        "schema_version": "1",
    }))
    .unwrap();
    let empty = root.join("empty");
    std::fs::create_dir_all(&empty).unwrap();
    let parsed_plain = snapshot::canon_value::CanonValue::parse(&plain).unwrap();
    preserve_production_render_blobs_from_canon(&empty, &parsed_plain).unwrap();
    assert!(
        !empty.join("production_render_blobs").exists(),
        "no blob directory may be created for a document that carries no render member"
    );

    std::fs::remove_dir_all(root).unwrap();
}

// --- synthetic H4CR stream builders --------------------------------------

fn push_record(
    out: &mut Vec<u8>,
    sequence: u64,
    game_hour_raw: i32,
    domain_id: u16,
    record_type: u16,
    payload: &[u8],
) {
    push_record_with_flags(
        out,
        sequence,
        game_hour_raw,
        domain_id,
        record_type,
        0,
        payload,
    );
}

fn push_record_with_flags(
    out: &mut Vec<u8>,
    sequence: u64,
    game_hour_raw: i32,
    domain_id: u16,
    record_type: u16,
    record_flags: u32,
    payload: &[u8],
) {
    out.extend_from_slice(COMPACT_RECORD_MAGIC);
    out.extend_from_slice(&COMPACT_RECORD_VERSION.to_le_bytes());
    out.extend_from_slice(&(COMPACT_RECORD_HEADER_LEN as u16).to_le_bytes());
    out.extend_from_slice(&sequence.to_le_bytes());
    out.extend_from_slice(&game_hour_raw.to_le_bytes());
    out.extend_from_slice(&domain_id.to_le_bytes());
    out.extend_from_slice(&record_type.to_le_bytes());
    out.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    out.extend_from_slice(&record_flags.to_le_bytes());
    out.extend_from_slice(payload);
}

fn push_str(payload: &mut Vec<u8>, value: &str) {
    payload.extend_from_slice(&(value.len() as u16).to_le_bytes());
    payload.extend_from_slice(value.as_bytes());
}

fn frame_end_payload() -> Vec<u8> {
    let mut p = Vec::new();
    p.extend_from_slice(&0u64.to_le_bytes());
    p.extend_from_slice(&0u64.to_le_bytes());
    p.extend_from_slice(&0u32.to_le_bytes());
    p.extend_from_slice(&0u32.to_le_bytes());
    p.extend_from_slice(&0u32.to_le_bytes());
    p
}

/// country_identity (domain 18): header + [tag_db_id u32][u16-len TAG] rows.
fn country_identity_payload(rows: &[(u32, &str)]) -> Vec<u8> {
    // Wave-4: default cosmetic marker = null (1) for every row — the ~50
    // existing call sites don't care about cosmetic tags.
    let with_cosmetic: Vec<(u32, &str, Option<&str>)> =
        rows.iter().map(|(id, tag)| (*id, *tag, None)).collect();
    country_identity_payload_with_cosmetic(&with_cosmetic)
}

/// Wave-4: country_identity payload with per-row cosmetic tag. The third
/// tuple element is `Some(tag)` for a cosmetic override (marker 2 + string),
/// or `None` for validated-null (marker 1). (Marker 0 = absent is exercised
/// by the dedicated absent test, which builds the payload by hand.)
fn country_identity_payload_with_cosmetic(rows: &[(u32, &str, Option<&str>)]) -> Vec<u8> {
    let mut p = Vec::new();
    p.extend_from_slice(&0u64.to_le_bytes()); // wall
    p.extend_from_slice(&(rows.len() as u32).to_le_bytes()); // row_count
    p.extend_from_slice(&(rows.len() as u32).to_le_bytes()); // changed
    p.extend_from_slice(&0u32.to_le_bytes()); // status
    for (tag_db_id, tag, cosmetic) in rows {
        p.extend_from_slice(&tag_db_id.to_le_bytes());
        push_str(&mut p, tag);
        match cosmetic {
            Some(cosmetic) => {
                p.push(2); // present
                push_str(&mut p, cosmetic);
            }
            None => p.push(1), // null
        }
    }
    p
}

fn domain47_payload(status_flags: u32, rows: &[domain47_lane::CharacterLaneRow<'_>]) -> Vec<u8> {
    domain47_lane::encode_payload(
        0,
        status_flags,
        domain47_lane::SCHEMA_ROOTS_VALIDATED
            | domain47_lane::SCHEMA_STATIC_NAME_CLOSURE
            | domain47_lane::SCHEMA_APPOINTED_FROM_ACTIVE_IDEAS,
        rows,
    )
}

fn domain57_payload(
    root_evidence_mask: u32,
    player_rows: Vec<session57_lane::PlayerCountryRow>,
    event_rows: Vec<session57_lane::SessionEventRow>,
    status_flags: u32,
) -> Vec<u8> {
    let source_flags = session57_lane::SOURCE_FLAG_DLL_NATIVE
        | if root_evidence_mask != 0 {
            session57_lane::SOURCE_FLAG_SESSION_ROOT_VALIDATED
        } else {
            0
        }
        | if root_evidence_mask & DOMAIN57_ROOT_CHAT_MESSAGES != 0 {
            session57_lane::SOURCE_FLAG_MESSAGE_HOOK_VALIDATED
        } else {
            0
        }
        | if root_evidence_mask & DOMAIN57_ROOT_PLAYER_EVENTS != 0 {
            session57_lane::SOURCE_FLAG_COMMAND_HOOK_VALIDATED
        } else {
            0
        };
    domain57_payload_with_source_flags(
        root_evidence_mask,
        source_flags,
        player_rows,
        event_rows,
        status_flags,
    )
}

fn domain57_payload_with_source_flags(
    root_evidence_mask: u32,
    source_flags: u32,
    player_rows: Vec<session57_lane::PlayerCountryRow>,
    event_rows: Vec<session57_lane::SessionEventRow>,
    status_flags: u32,
) -> Vec<u8> {
    session57_lane::encode_payload(&session57_lane::SessionMetadataFrame {
        game_hour_raw: raw_for(16_959_360),
        status_flags,
        source_flags,
        schema_flags: 0,
        root_evidence_mask,
        world_tension_fixed5: None,
        world_tension_details: None,
        player_country_rows: player_rows,
        event_rows,
    })
}

#[allow(clippy::too_many_arguments)]
fn domain57_a15_event_row(
    kind: session57_lane::SessionEventKind,
    actor_key_hash: u64,
    actor_name: &str,
    text: &str,
    tag_db_id: u32,
    value_i32: i32,
    related_value_i32: i32,
    command_sequence: u64,
    event_source_id: u32,
    event_state: u32,
) -> session57_lane::SessionEventRow {
    session57_lane::SessionEventRow {
        kind,
        flags: session57_lane::EVENT_FLAG_DIRECT_CAPTURE
            | (!text.is_empty())
                .then_some(session57_lane::EVENT_FLAG_TEXT_PRESENT)
                .unwrap_or(0),
        actor_key_hash,
        actor_name: actor_name.into(),
        text: text.into(),
        tag_db_id,
        value_i32,
        related_value_i32,
        command_sequence,
        event_hour_raw: raw_for(16_959_360),
        event_source_id,
        event_state,
    }
}

fn domain57_player_row(tag: &str, tag_db_id: u32) -> session57_lane::PlayerCountryRow {
    session57_lane::PlayerCountryRow {
        player_key_hash: 42,
        player_name: "fixture name ignored".into(),
        country_tag: tag.into(),
        tag_db_id,
        session_slot: 7,
        flags: session57_lane::PLAYER_FLAG_HUMAN
            | session57_lane::PLAYER_FLAG_HOST
            | session57_lane::PLAYER_FLAG_CONNECTED,
        valid_from_hour_raw: raw_for(16_959_360),
    }
}

fn domain57_event_row(
    kind: session57_lane::SessionEventKind,
    value_i32: i32,
) -> session57_lane::SessionEventRow {
    session57_lane::SessionEventRow {
        kind,
        flags: session57_lane::EVENT_FLAG_DIRECT_CAPTURE,
        actor_key_hash: 0,
        actor_name: String::new(),
        text: if matches!(
            kind,
            session57_lane::SessionEventKind::Chat
                | session57_lane::SessionEventKind::SystemMessage
                | session57_lane::SessionEventKind::Alert
                | session57_lane::SessionEventKind::Notification
        ) {
            "fixture text".into()
        } else {
            String::new()
        },
        tag_db_id: 0,
        value_i32,
        related_value_i32: 0,
        command_sequence: 0,
        event_hour_raw: raw_for(16_959_360),
        event_source_id: 0,
        event_state: 0,
    }
}

fn domain57_x12_event_row(
    kind: session57_lane::SessionEventKind,
    speed_raw: i32,
    paused: bool,
    sequence: u64,
    source: u32,
) -> session57_lane::SessionEventRow {
    let (value_i32, related_value_i32) = match kind {
        session57_lane::SessionEventKind::GameSpeed => {
            (speed_raw, if paused { 1 } else { 0 })
        }
        session57_lane::SessionEventKind::Pause => {
            (if paused { 1 } else { 0 }, speed_raw)
        }
        _ => panic!("X12 fixture row must be speed or pause"),
    };
    session57_lane::SessionEventRow {
        kind,
        flags: session57_lane::EVENT_FLAG_DIRECT_CAPTURE
            | session57_lane::EVENT_FLAG_TRANSITION_HOOK,
        actor_key_hash: 7,
        actor_name: String::new(),
        text: String::new(),
        tag_db_id: 0,
        value_i32,
        related_value_i32,
        command_sequence: sequence,
        event_hour_raw: raw_for(16_959_360),
        event_source_id: source,
        event_state: 0x3E80_0000,
    }
}

