#[test]
fn chunk3_folds_d45_v5_direct_history_as_cumulative_pointer_free_root() {
    let snapshot = snapshot_for_domain_records_with_flags(vec![(
        45,
        chunk3_frd_v5_direct_payload(),
        COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
    )]);
    let rows = snapshot["_r2_direct_frd_transitions"]["transitions"]
        .as_array()
        .expect("validated direct history");
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0]["sequence"], json!(1));
    assert_eq!(rows[0]["kind"], json!("focus_completion"));
    assert_eq!(rows[0]["hook_rva"], json!(0x002c_ef60u32));
    assert_eq!(rows[0]["original_returned"], json!(true));
    assert_eq!(snapshot["_r2_direct_frd_transitions"]["hook_epoch"], json!(1));
    assert!(rows[0].get("pointer").is_none());
    // delta_replay lane: the frame carries a v4 per-frame delta. The first
    // frame's delta IS the whole history so far (base 1, cumulative 1); replay
    // folds these deltas back into the full cumulative history.
    let frd = &snapshot["_r2_direct_frd_transitions"];
    assert_eq!(frd["schema_version"], json!(4));
    assert_eq!(frd["delta_base_sequence"], json!(1));
    assert_eq!(frd["cumulative_count"], json!(1));
}

/// delta_replay lane: two hours, each with one new FRD transition. The
/// snapshots must carry DISJOINT, CONTIGUOUS per-hour deltas — hour 0 emits
/// sequence 1 (base 1, cumulative 1), hour 1 emits ONLY sequence 2 (base 2,
/// cumulative 2), never re-emitting hour 0's history. This is the property the
/// replay accumulator folds back; a producer that re-shipped the whole history
/// each hour would carry both rows in the second frame.
#[test]
fn chunk3_folds_d45_v5_direct_history_as_disjoint_per_hour_deltas() {
    use direct_frd_transitions_live::{
        DirectEventBatch, DirectEventCarrier, DirectEventKind, DirectEventStateSummary,
        UnsequencedDirectEventRow,
    };
    let h0 = 16_959_360i64;
    let h1 = h0 + 1;
    let raw0 = raw_for(h0);
    let raw1 = raw_for(h1);

    let mut carrier = DirectEventCarrier::new();
    let owner = carrier.allocate_instance_id().unwrap();
    let subject = carrier.allocate_instance_id().unwrap();
    let make_row = |game_hour_raw: i32| UnsequencedDirectEventRow {
        kind: DirectEventKind::FocusCompleted,
        thread_id: 23,
        game_hour_raw,
        root_rva: DirectEventKind::FocusCompleted.expected_root_rva_a729(),
        owner_instance_id: owner,
        subject_instance_id: subject,
        argument_instance_id: direct_frd_transitions_live::OpaqueInstanceId::NONE,
        owner_key: 1,
        subject_token_hash: 1,
        subject_key: 0,
        input_bits: 0,
        return_bits: 1,
        before: DirectEventStateSummary::default(),
        after: DirectEventStateSummary {
            state_bits: 1 << 63,
            ..DirectEventStateSummary::default()
        },
    };
    let mask = DirectEventKind::FocusCompleted.root_mask_bit();
    let root_mask = direct_frd_transitions_live::D45_V5_DIRECT_EVENT_REQUIRED_ROOT_MASK;

    // Hour 0: capture + drain one row (sequence 1), drain_sequence 1.
    carrier.capture(make_row(raw0)).unwrap();
    let rows0 = carrier.drain_rows().unwrap();
    let batch0 = DirectEventBatch {
        hook_epoch: 1,
        drain_sequence: 1,
        installed_root_mask: root_mask,
        observed_kind_mask: mask,
        sequence_cursor: 2,
        producer_complete: true,
        evidence_fixture: false,
        rows: rows0,
    };
    // Hour 1: the SAME carrier continues at sequence 2, drain_sequence 2.
    carrier.capture(make_row(raw1)).unwrap();
    let rows1 = carrier.drain_rows().unwrap();
    let batch1 = DirectEventBatch {
        hook_epoch: 1,
        drain_sequence: 2,
        installed_root_mask: root_mask,
        observed_kind_mask: mask,
        sequence_cursor: 3,
        producer_complete: true,
        evidence_fixture: false,
        rows: rows1,
    };

    let mut stream = Vec::new();
    let mut seq = 0u64;
    let mut push = |stream: &mut Vec<u8>, raw: i32, domain: u16, ty: u16, flags: u32, payload: &[u8]| {
        seq += 1;
        push_record_with_flags(stream, seq, raw, domain, ty, flags, payload);
    };
    push(
        &mut stream,
        raw0,
        45,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
        &chunk3_frd_v5_direct_batch_payload(&batch0),
    );
    push(
        &mut stream,
        raw0,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        0,
        &frame_end_payload(),
    );
    push(
        &mut stream,
        raw1,
        45,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
        &chunk3_frd_v5_direct_batch_payload(&batch1),
    );
    push(
        &mut stream,
        raw1,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        0,
        &frame_end_payload(),
    );

    let mut fold = WorldFold::new("chunk3_delta_test");
    fold.ingest_stream(&stream);
    let snaps = fold.finish();
    assert_eq!(snaps.len(), 2, "two hours -> two snapshots");
    let s0 = parse(&snaps[0].2);
    let s1 = parse(&snaps[1].2);

    let frd0 = &s0["_r2_direct_frd_transitions"];
    assert_eq!(frd0["schema_version"], json!(4));
    assert_eq!(frd0["delta_base_sequence"], json!(1));
    assert_eq!(frd0["cumulative_count"], json!(1));
    let rows0 = frd0["transitions"].as_array().expect("hour0 delta");
    assert_eq!(rows0.len(), 1);
    assert_eq!(rows0[0]["sequence"], json!(1));

    let frd1 = &s1["_r2_direct_frd_transitions"];
    assert_eq!(frd1["schema_version"], json!(4));
    // Hour 1 carries ONLY its own new row (base 2), NOT hour 0's history.
    assert_eq!(frd1["delta_base_sequence"], json!(2));
    assert_eq!(frd1["cumulative_count"], json!(2));
    let rows1 = frd1["transitions"].as_array().expect("hour1 delta");
    assert_eq!(rows1.len(), 1, "second frame carries only its own delta");
    assert_eq!(rows1[0]["sequence"], json!(2));
}

/// The direct-FRD history is cumulative and the replay consumer refuses one
/// longer than `MAX_FRD_DIRECT_TRANSITIONS`, discarding the WHOLE view. The
/// producer's ceiling is therefore that number exactly: a history OF that
/// length is readable and must be admitted, one row more is not.
///
/// Pinned absolutely. Spelling the boundary as the constant would pass for any
/// value the constant took, and the value is the cross-workspace contract.
#[test]
fn chunk3_d45_direct_history_ceiling_is_the_exact_shared_row_bound() {
    assert_eq!(portable_admission::MAX_FRD_DIRECT_TRANSITIONS, 1_000_000);
    assert!(!frd_direct_history_capacity_exceeded(0, 1_000_000));
    assert!(!frd_direct_history_capacity_exceeded(999_999, 1));
    assert!(!frd_direct_history_capacity_exceeded(1_000_000, 0));
    assert!(frd_direct_history_capacity_exceeded(1_000_000, 1));
    assert!(frd_direct_history_capacity_exceeded(999_999, 2));
    // Saturating, not wrapping: an absurd length must not fold back into the
    // admitted range.
    assert!(frd_direct_history_capacity_exceeded(usize::MAX, 1));
}

/// ...and the fold actually applies it. Before this, the fold appended without
/// any ceiling: the recorder kept building a history that replay would throw
/// away in full, and nothing said so until the recording was already over.
///
/// The history has to be AT the ceiling for the next drain to cross it, so this
/// test allocates that many rows once (~120 MB transient). There is no smaller
/// state that reaches the boundary, and the boundary is what is under test.
#[test]
fn chunk3_d45_direct_history_refuses_to_grow_past_the_ceiling_replay_admits() {
    use direct_frd_transitions_live::{
        DirectEventKind, DirectEventRow, DirectEventStateSummary, OpaqueInstanceId,
    };
    let seed = DirectEventRow {
        sequence: 1,
        kind: DirectEventKind::FocusCompleted,
        thread_id: 23,
        game_hour_raw: raw_for(16_959_360),
        root_rva: DirectEventKind::FocusCompleted.expected_root_rva_a729(),
        owner_instance_id: OpaqueInstanceId::NONE,
        subject_instance_id: OpaqueInstanceId::NONE,
        argument_instance_id: OpaqueInstanceId::NONE,
        owner_key: 1,
        subject_token_hash: 1,
        subject_key: 0,
        input_bits: 0,
        return_bits: 1,
        before: DirectEventStateSummary::default(),
        after: DirectEventStateSummary {
            state_bits: 1 << 63,
            ..DirectEventStateSummary::default()
        },
    };

    // At the ceiling, so the incoming drain would carry it past: the fold stops
    // and says so instead of building a history replay cannot read. (Which side
    // of the boundary is admitted is pinned by
    // `chunk3_d45_direct_history_ceiling_is_the_exact_shared_row_bound`; folding
    // an admitted million-row history here would spend the test's time
    // projecting it to JSON, not exercising the rule.)
    let mut fold = WorldFold::new("d45_direct_history_past_ceiling");
    fold.frd_direct_transitions =
        vec![seed; portable_admission::MAX_FRD_DIRECT_TRANSITIONS];
    fold.ingest_stream(&d45_v5_direct_stream());
    assert!(fold.frd_direct_history_failed);
    assert!(fold.frd_direct_transitions.is_empty());
    assert_eq!(fold.frd_direct_last_sequence, None);
}

/// One D45 schema-v5 direct-hook record plus its frame end, as a stream.
fn d45_v5_direct_stream() -> Vec<u8> {
    let raw = raw_for(16_959_360);
    let mut stream = Vec::new();
    push_record_with_flags(
        &mut stream,
        1,
        raw,
        45,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
        &chunk3_frd_v5_direct_payload(),
    );
    push_record(
        &mut stream,
        2,
        raw,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );
    stream
}

#[test]
fn chunk3_folds_d45_v5_empty_logical_stream_baseline_after_prior_drains() {
    let batch = direct_frd_transitions_live::DirectEventBatch {
        hook_epoch: 7,
        drain_sequence: 4,
        installed_root_mask:
            direct_frd_transitions_live::D45_V5_DIRECT_EVENT_REQUIRED_ROOT_MASK,
        observed_kind_mask:
            direct_frd_transitions_live::DirectEventKind::FocusCompleted.root_mask_bit(),
        sequence_cursor: 3,
        producer_complete: true,
        evidence_fixture: false,
        rows: Vec::new(),
    };
    let payload = chunk3_frd_v5_direct_batch_payload(&batch);
    crate::domain_data_authority::summarize_domain_data_payload(
        45,
        &payload,
        crate::domain_data_authority::DomainDataContext {
            record_flags: COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
            ..crate::domain_data_authority::DomainDataContext::default()
        },
    )
    .expect("empty process-continuous D45 baseline is exact");

    let snapshot = snapshot_for_domain_records_with_flags(vec![(
        45,
        payload,
        COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
    )]);
    assert_eq!(
        snapshot["_r2_direct_frd_transitions"]["hook_epoch"],
        json!(7)
    );
    assert_eq!(
        snapshot["_r2_direct_frd_transitions"]["last_drain_sequence"],
        json!(4)
    );
    assert_eq!(
        snapshot["_r2_direct_frd_transitions"]["transitions"],
        json!([])
    );
    // §7.3.1's opening anchor, on the fixture that already had the shape: this
    // baseline is EMPTY and its cursor is 3, so the history it opens begins at
    // raw 3 and there is no row for a consumer to read that from. Declared, not
    // inferred -- see `frd_direct_accumulated_base_sequence`.
    assert_eq!(
        snapshot["_r2_direct_frd_transitions"]["direct_history_base_sequence"],
        json!(3),
        "a stream that attached after prior drains must SAY where its history opens; a \
         consumer reading only delta_base_sequence takes it as raw 1 and refuses every row"
    );
    assert_eq!(
        snapshot["_r2_direct_frd_transitions"]["direct_history_reset"],
        json!(false),
        "and an opening is not a reset: nothing was discarded"
    );
    assert!(snapshot["provenance"]["collector"]["domain_problems"]
        .as_array()
        .unwrap()
        .is_empty());
}

#[test]
