fn append_d43_mts1_stockpiles(payload: &mut Vec<u8>, countries: &[(u32, &[(u32, i64)])]) {
    let item_count = countries.iter().map(|(_, rows)| rows.len()).sum::<usize>();
    let segment_len = MARKET_TRADE_STOCKPILE_HEADER_LEN
        + countries.len() * MARKET_TRADE_STOCKPILE_COUNTRY_ROW_LEN
        + item_count * MARKET_TRADE_STOCKPILE_ITEM_ROW_LEN;
    payload.extend_from_slice(MARKET_TRADE_STOCKPILE_TRAILER_MAGIC);
    payload.extend_from_slice(&MARKET_TRADE_STOCKPILE_TRAILER_VERSION.to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_STOCKPILE_HEADER_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_STOCKPILE_COUNTRY_ROW_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_STOCKPILE_ITEM_ROW_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(segment_len as u32).to_le_bytes());
    payload.extend_from_slice(&(countries.len() as u32).to_le_bytes());
    payload.extend_from_slice(&(item_count as u32).to_le_bytes());
    payload.extend_from_slice(&(countries.len() as u32).to_le_bytes());
    payload.extend_from_slice(&(FIXED_SCALE as u32).to_le_bytes());
    payload.extend_from_slice(&MARKET_TRADE_STOCKPILE_GLOBAL_FLAGS.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    let mut item_first = 0u32;
    for (tag_db_id, rows) in countries {
        payload.extend_from_slice(&tag_db_id.to_le_bytes());
        payload.extend_from_slice(&item_first.to_le_bytes());
        payload.extend_from_slice(&(rows.len() as u32).to_le_bytes());
        payload.extend_from_slice(&MARKET_TRADE_STOCKPILE_COUNTRY_COMPLETE.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        item_first += rows.len() as u32;
    }
    for (_, rows) in countries {
        for (ordinal, (variant_id, amount_raw)) in rows.iter().enumerate() {
            payload.extend_from_slice(&variant_id.to_le_bytes());
            payload.extend_from_slice(&70u32.to_le_bytes());
            payload.extend_from_slice(&(ordinal as u32).to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
            payload.extend_from_slice(&amount_raw.to_le_bytes());
        }
    }
}

fn append_d43_mtrf_resource_flow(payload: &mut Vec<u8>, countries: &[(u32, [[i64; 7]; 6])]) {
    let widened = countries
        .iter()
        .map(|(tag_db_id, pools)| (*tag_db_id, pools.iter().map(|p| p.to_vec()).collect()))
        .collect::<Vec<(u32, Vec<Vec<i64>>)>>();
    append_d43_mtrf_resource_flow_with_count(payload, &widened, 7);
}

/// MTRF v3 with an explicit resource count. The width is a parameter because
/// the value vector is count-prefixed: a builder that could only make
/// seven-wide rows could not exercise the case the fixed vector made
/// impossible.
fn append_d43_mtrf_resource_flow_with_count(
    payload: &mut Vec<u8>,
    countries: &[(u32, Vec<Vec<i64>>)],
    resource_count: u32,
) {
    let row_len = MARKET_TRADE_RESOURCE_FLOW_ROW_HEADER_LEN + (resource_count as usize) * 8;
    payload.extend_from_slice(MARKET_TRADE_RESOURCE_FLOW_TRAILER_MAGIC);
    payload.extend_from_slice(&MARKET_TRADE_RESOURCE_FLOW_TRAILER_VERSION.to_le_bytes());
    payload
        .extend_from_slice(&(MARKET_TRADE_RESOURCE_FLOW_TRAILER_HEADER_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(row_len as u16).to_le_bytes());
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload.extend_from_slice(&((countries.len() * 6) as u32).to_le_bytes());
    payload.extend_from_slice(&(countries.len() as u32).to_le_bytes());
    payload.extend_from_slice(&(FIXED_SCALE as u32).to_le_bytes());
    payload.extend_from_slice(&resource_count.to_le_bytes());
    payload.extend_from_slice(&MARKET_TRADE_RESOURCE_FLOW_KIND_MASK.to_le_bytes());
    let kinds = [
        MARKET_TRADE_RESOURCE_FLOW_KIND_PRODUCED,
        MARKET_TRADE_RESOURCE_FLOW_KIND_IMPORTED,
        MARKET_TRADE_RESOURCE_FLOW_KIND_EXPORTED,
        MARKET_TRADE_RESOURCE_FLOW_KIND_USED,
        MARKET_TRADE_RESOURCE_FLOW_KIND_TO_EXPORT,
        MARKET_TRADE_RESOURCE_FLOW_KIND_BASE_EXPORT,
    ];
    for (tag_db_id, pools) in countries {
        for (flow_kind, values_raw) in kinds.into_iter().zip(pools) {
            payload.extend_from_slice(&tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flow_kind.to_le_bytes());
            payload.extend_from_slice(&resource_count.to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
            for value in values_raw {
                payload.extend_from_slice(&value.to_le_bytes());
            }
        }
    }
}

fn append_d43_mtrh_factory_headers(payload: &mut Vec<u8>, rows: &[(u32, i32, i32, i32)]) {
    payload.extend_from_slice(MARKET_TRADE_FACTORY_HEADER_TRAILER_MAGIC);
    payload.extend_from_slice(&MARKET_TRADE_FACTORY_HEADER_TRAILER_VERSION.to_le_bytes());
    payload
        .extend_from_slice(&(MARKET_TRADE_FACTORY_HEADER_TRAILER_HEADER_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_FACTORY_HEADER_ROW_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload.extend_from_slice(&(rows.len() as u32).to_le_bytes());
    payload.extend_from_slice(&(rows.len() as u32).to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    for (tag_db_id, total, used, available) in rows {
        payload.extend_from_slice(&tag_db_id.to_le_bytes());
        payload.extend_from_slice(&total.to_le_bytes());
        payload.extend_from_slice(&used.to_le_bytes());
        payload.extend_from_slice(&available.to_le_bytes());
    }
}

/// The identity-only `MTRR` the producer emits when it discovered the resource
/// set but its per-country rows failed: the set is stated, the rows are not.
/// This is the shape every `MTRF`-carrying payload now has.
fn append_d43_mtrr_identity_only(payload: &mut Vec<u8>) {
    let tokens: Vec<String> = MARKET_TRADE_RESOURCE_NAMES
        .iter()
        .map(|name| (*name).to_string())
        .collect();
    append_d43_mtrr_resource_rows_with_identity(
        payload,
        &[],
        7,
        &tokens,
        MARKET_TRADE_RESOURCE_ROW_TRAILER_VERSION,
    );
}

/// A VANILLA recording: the seven resources the game ships with, stated on the
/// wire exactly as any v3 recording states its set. This is a fixture of the
/// unmodded case, not a fallback -- the names reach the projection off the
/// trailer here, the same way a mod's would.
fn append_d43_mtrr_resource_rows(payload: &mut Vec<u8>, tag_db_ids: &[u32]) {
    let tokens: Vec<String> = MARKET_TRADE_RESOURCE_NAMES
        .iter()
        .map(|name| (*name).to_string())
        .collect();
    append_d43_mtrr_resource_rows_with_identity(
        payload,
        tag_db_ids,
        7,
        &tokens,
        MARKET_TRADE_RESOURCE_ROW_TRAILER_VERSION,
    );
}

/// The resource count is a parameter because `MTRR` is count-prefixed: a
/// builder that could only make seven-resource trailers could not exercise the
/// width the fixed vector made unrepresentable.
fn append_d43_mtrr_resource_rows_with_count(
    payload: &mut Vec<u8>,
    tag_db_ids: &[u32],
    resource_count: u32,
    version: u16,
) {
    // A v3 trailer that stated no identity would not be a v3 trailer, so the
    // default builder supplies a distinct token per slot. Tests that care about
    // the tokens themselves use `append_d43_mtrr_resource_rows_with_identity`.
    let tokens = (0..resource_count)
        .map(|slot| format!("res_{slot}"))
        .collect::<Vec<_>>();
    append_d43_mtrr_resource_rows_with_identity(payload, tag_db_ids, resource_count, &tokens, version);
}

/// Build an `MTRR` trailer stating an explicit resource set.
///
/// `tokens` is written into the v3 identity block verbatim, including cases the
/// decoder must refuse -- an over-long token, a non-token body, a repeat. For
/// v1/v2 it is ignored, because those versions have nowhere to put it.
fn append_d43_mtrr_resource_rows_with_identity(
    payload: &mut Vec<u8>,
    tag_db_ids: &[u32],
    resource_count: u32,
    tokens: &[String],
    version: u16,
) {
    append_d43_mtrr_resource_rows_with_oil_slot(
        payload,
        tag_db_ids,
        resource_count,
        tokens,
        version,
        0,
    );
}

/// The same trailer with the OIL SLOT as a parameter. Vanilla puts oil first,
/// so every other fixture here passes 0; a mod that reorders or prepends a
/// resource in `common/resources` does not, and that is the case the decoder
/// must resolve from the row's own stamped model rather than from its position.
fn append_d43_mtrr_resource_rows_with_oil_slot(
    payload: &mut Vec<u8>,
    tag_db_ids: &[u32],
    resource_count: u32,
    tokens: &[String],
    version: u16,
    oil_slot: u32,
) {
    let carries_identity = version == MARKET_TRADE_RESOURCE_ROW_TRAILER_VERSION;
    payload.extend_from_slice(MARKET_TRADE_RESOURCE_ROW_TRAILER_MAGIC);
    payload.extend_from_slice(&version.to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_RESOURCE_ROW_TRAILER_HEADER_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_RESOURCE_ROW_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload.extend_from_slice(&(tag_db_ids.len() as u32 * resource_count).to_le_bytes());
    payload.extend_from_slice(&(tag_db_ids.len() as u32).to_le_bytes());
    payload.extend_from_slice(&resource_count.to_le_bytes());
    payload.extend_from_slice(&1u32.to_le_bytes());
    payload.extend_from_slice(
        &(if carries_identity {
            STRATEGIC_RESOURCE_IDENTITY_STRIDE as u32
        } else {
            0
        })
        .to_le_bytes(),
    );
    if carries_identity {
        for token in tokens {
            let bytes = token.as_bytes();
            payload.extend_from_slice(&(bytes.len() as u16).to_le_bytes());
            let mut body = vec![0u8; MAX_STRATEGIC_RESOURCE_TOKEN_LEN];
            let copied = bytes.len().min(MAX_STRATEGIC_RESOURCE_TOKEN_LEN);
            body[..copied].copy_from_slice(&bytes[..copied]);
            payload.extend_from_slice(&body);
        }
    }
    for tag_db_id in tag_db_ids {
        for resource_index in 0..resource_count {
            let oil = resource_index == oil_slot;
            let balance = if oil { -4 } else { resource_index as i32 };
            payload.extend_from_slice(&tag_db_id.to_le_bytes());
            payload.extend_from_slice(&resource_index.to_le_bytes());
            payload.extend_from_slice(&resource_index.to_le_bytes());
            payload.extend_from_slice(
                &(if oil {
                    MARKET_TRADE_RESOURCE_NEEDED_CURRENT_MAX
                } else {
                    MARKET_TRADE_RESOURCE_NEEDED_SURPLUS
                })
                .to_le_bytes(),
            );
            payload.extend_from_slice(&balance.to_le_bytes());
            payload.extend_from_slice(&(10 + resource_index as i32).to_le_bytes());
            payload.extend_from_slice(&(2 + resource_index as i32).to_le_bytes());
            payload.extend_from_slice(&(1 + resource_index as i32).to_le_bytes());
            payload.extend_from_slice(&3i32.to_le_bytes());
            payload.extend_from_slice(&4i32.to_le_bytes());
            payload.extend_from_slice(&(if oil { -12i32 } else { balance }).to_le_bytes());
            payload.extend_from_slice(&(if oil { -12i32 } else { 0 }).to_le_bytes());
            payload.extend_from_slice(&(if oil { -8i32 } else { 0 }).to_le_bytes());
            payload.extend_from_slice(
                &(if oil {
                    MARKET_TRADE_RESOURCE_FLAGS_OIL
                } else {
                    0
                })
                .to_le_bytes(),
            );
            payload.extend_from_slice(&(resource_index + 1).to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
        }
    }
}

fn append_d43_mtrd_classic_deal(payload: &mut Vec<u8>, exporter: u32, importer: u32) {
    append_d43_mtrd_classic_deal_for_resource(payload, exporter, importer, 4);
}

/// The resource SLOT is a parameter: an MTRD row names a resource by slot and
/// states no count of its own, so a fixture must be able to name a slot outside
/// what the fold can name.
fn append_d43_mtrd_classic_deal_for_resource(
    payload: &mut Vec<u8>,
    exporter: u32,
    importer: u32,
    resource_index: u32,
) {
    payload.extend_from_slice(MARKET_TRADE_CLASSIC_DEAL_TRAILER_MAGIC);
    payload.extend_from_slice(&MARKET_TRADE_CLASSIC_DEAL_TRAILER_VERSION.to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_CLASSIC_DEAL_TRAILER_HEADER_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_CLASSIC_DEAL_ROW_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload.extend_from_slice(&2u32.to_le_bytes());
    payload.extend_from_slice(&2u32.to_le_bytes());
    payload.extend_from_slice(&(FIXED_SCALE as u32).to_le_bytes());
    payload.extend_from_slice(&2u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&exporter.to_le_bytes());
    payload.extend_from_slice(&importer.to_le_bytes());
    // Frozen MTRD identity layout (high to low): reserved:u16,
    // exporter:u16, importer:u16, resource:u8, one-based ordinal:u8.
    // Build it from the fixture arguments so the reciprocal-row identity
    // witness cannot silently drift away from the row fields.
    let deal_id = (u64::from(exporter) << 32)
        | (u64::from(importer) << 16)
        | (u64::from(resource_index) << 8)
        | 1;
    for (owner, counterpart, direction) in [
        (
            exporter,
            importer,
            MARKET_TRADE_CLASSIC_DEAL_DIRECTION_EXPORT,
        ),
        (
            importer,
            exporter,
            MARKET_TRADE_CLASSIC_DEAL_DIRECTION_IMPORT,
        ),
    ] {
        payload.extend_from_slice(&owner.to_le_bytes());
        payload.extend_from_slice(&counterpart.to_le_bytes());
        payload.extend_from_slice(&resource_index.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload.extend_from_slice(&direction.to_le_bytes());
        payload.extend_from_slice(&MARKET_TRADE_CLASSIC_DEAL_ROUTE_SEA.to_le_bytes());
        payload.extend_from_slice(&MARKET_TRADE_CLASSIC_DEAL_FLAG_EXACT.to_le_bytes());
        payload.extend_from_slice(
            &MARKET_TRADE_CLASSIC_DEAL_STATUS_NO_TRADE_INFLUENCE.to_le_bytes(),
        );
        payload.extend_from_slice(&deal_id.to_le_bytes());
        payload.extend_from_slice(&800_000i64.to_le_bytes());
        payload.extend_from_slice(&720_000i64.to_le_bytes());
        payload.extend_from_slice(&1_600_000i64.to_le_bytes());
        payload.extend_from_slice(&100_000i64.to_le_bytes());
        payload.extend_from_slice(&90_000i64.to_le_bytes());
        payload.extend_from_slice(&8i32.to_le_bytes());
        payload.extend_from_slice(&3i32.to_le_bytes());
        payload.extend_from_slice(&5i32.to_le_bytes());
        payload.extend_from_slice(&0i32.to_le_bytes());
    }
}

/// Two countries that trade with each other in BOTH directions: four MTRD rows,
/// two deals, and every country owning one export row and one import row.
///
/// This is the shape the collector's classic-deal walk produces for any pair
/// that both imports and exports, and it is the shape no fixture had until
/// lane/BW. `orders` is `[a_export, a_import, b_export, b_import]` so a caller
/// can state the per-owner numbering explicitly: the producer's two direction
/// counters each start at zero, so the un-renumbered form is `[0, 0, 0, 0]`.
fn append_d43_mtrd_two_way_deals(payload: &mut Vec<u8>, a: u32, b: u32, orders: [u32; 4]) {
    append_d43_mtrd_two_way_deals_versioned(
        payload,
        a,
        b,
        orders,
        MARKET_TRADE_CLASSIC_DEAL_TRAILER_VERSION,
        &[],
    );
}

/// The same world, written under an arbitrary version word and with an
/// arbitrary incomplete-owner block.
///
/// Both are parameters rather than derived from each other so a fixture can
/// state a DISAGREEMENT — a v3 body labelled v2, an incomplete owner that is not
/// a witness, a block out of order — which is what pins the parser's refusals
/// rather than its happy path.
fn append_d43_mtrd_two_way_deals_versioned(
    payload: &mut Vec<u8>,
    a: u32,
    b: u32,
    orders: [u32; 4],
    version: u16,
    incomplete: &[u32],
) {
    const RESOURCE_INDEX: u32 = 4;
    let deal_id = |exporter: u32, importer: u32| {
        (u64::from(exporter) << 32)
            | (u64::from(importer) << 16)
            | (u64::from(RESOURCE_INDEX) << 8)
            | 1
    };
    payload.extend_from_slice(MARKET_TRADE_CLASSIC_DEAL_TRAILER_MAGIC);
    payload.extend_from_slice(&version.to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_CLASSIC_DEAL_TRAILER_HEADER_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&(MARKET_TRADE_CLASSIC_DEAL_ROW_LEN as u16).to_le_bytes());
    payload.extend_from_slice(&0u16.to_le_bytes());
    payload.extend_from_slice(&4u32.to_le_bytes());
    payload.extend_from_slice(&2u32.to_le_bytes());
    payload.extend_from_slice(&(FIXED_SCALE as u32).to_le_bytes());
    payload.extend_from_slice(&2u32.to_le_bytes());
    payload.extend_from_slice(&(incomplete.len() as u32).to_le_bytes());
    payload.extend_from_slice(&a.to_le_bytes());
    payload.extend_from_slice(&b.to_le_bytes());
    for owner in incomplete {
        payload.extend_from_slice(&owner.to_le_bytes());
    }
    for (owner, counterpart, direction, visible_order, deal) in [
        (
            a,
            b,
            MARKET_TRADE_CLASSIC_DEAL_DIRECTION_EXPORT,
            orders[0],
            deal_id(a, b),
        ),
        (
            a,
            b,
            MARKET_TRADE_CLASSIC_DEAL_DIRECTION_IMPORT,
            orders[1],
            deal_id(b, a),
        ),
        (
            b,
            a,
            MARKET_TRADE_CLASSIC_DEAL_DIRECTION_EXPORT,
            orders[2],
            deal_id(b, a),
        ),
        (
            b,
            a,
            MARKET_TRADE_CLASSIC_DEAL_DIRECTION_IMPORT,
            orders[3],
            deal_id(a, b),
        ),
    ] {
        payload.extend_from_slice(&owner.to_le_bytes());
        payload.extend_from_slice(&counterpart.to_le_bytes());
        payload.extend_from_slice(&RESOURCE_INDEX.to_le_bytes());
        payload.extend_from_slice(&visible_order.to_le_bytes());
        payload.extend_from_slice(&direction.to_le_bytes());
        payload.extend_from_slice(&MARKET_TRADE_CLASSIC_DEAL_ROUTE_SEA.to_le_bytes());
        payload.extend_from_slice(&MARKET_TRADE_CLASSIC_DEAL_FLAG_EXACT.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload.extend_from_slice(&deal.to_le_bytes());
        payload.extend_from_slice(&800_000i64.to_le_bytes());
        payload.extend_from_slice(&720_000i64.to_le_bytes());
        payload.extend_from_slice(&1_600_000i64.to_le_bytes());
        payload.extend_from_slice(&100_000i64.to_le_bytes());
        payload.extend_from_slice(&90_000i64.to_le_bytes());
        payload.extend_from_slice(&8i32.to_le_bytes());
        payload.extend_from_slice(&3i32.to_le_bytes());
        payload.extend_from_slice(&5i32.to_le_bytes());
        payload.extend_from_slice(&0i32.to_le_bytes());
    }
}

/// A country that both imports and exports folds only when its `visible_order`
/// is dense across BOTH of its directions.
///
/// This is the consumer half of the seam the collector's
/// `compact_market_trade_classic_deal_renumber` sits on. The producer numbers a
/// route's two halves from two independent per-direction counters, so before
/// lane/BW every such country published two rows numbered 0 — and this parser
/// rejects the whole MTRD trailer, and with it the whole D43 payload, on
/// exactly that. The family has never published a row in live capture, so
/// nothing had ever exercised it.
///
/// What production change makes this fail: relaxing the CONTIGUITY check in
/// `parse_market_trade_classic_deal_trailer`. It is deliberately not claimed to
/// pin the `seen.insert((owner, visible_order))` uniqueness check as well:
/// sorted duplicates can never equal `0..n`, so contiguity rejects every input
/// uniqueness would, and no MTRD exists that isolates the uniqueness guard.
/// Both cases below are therefore contiguity cases -- one with a duplicate, one
/// unique but gapped -- and the second is the one that cannot be caught by
/// anything else.
///
/// MUTATION RUN (`--release`): disabled the contiguity check in
/// `parse_market_trade_classic_deal_trailer`.
/// OBSERVED: FAILED -- "an owner numbered 0 and 2 is not dense, and the trailer
/// is rejected", with ENG's two deals projected under `deals_complete: true`
/// and `visible_order` 0 and 2.
#[test]
fn d43_mtrd_two_way_deals_fold_only_under_dense_per_owner_visible_order() {
    let dense = {
        let mut payload = d43_empty_payload();
        append_d43_mtrr_resource_rows(&mut payload, &[34, 67]);
        append_d43_mtrd_two_way_deals(&mut payload, 34, 67, [0, 1, 0, 1]);
        chunk1_one_snapshot(vec![
            (18, country_identity_payload(&[(34, "SAF"), (67, "ENG")])),
            (43, payload),
        ])
    };
    let trade = &dense["countries"]["ENG"]["economy"]["resource_trade"];
    assert_eq!(
        trade["deals_complete"],
        json!(true),
        "a bidirectional pair numbered densely per owner folds"
    );
    assert_eq!(
        trade["deals"].as_array().map(Vec::len),
        Some(2),
        "and the country carries both of its deals"
    );

    // The producer's un-renumbered form: each direction counted from zero, so
    // ENG owns two rows both numbered 0.
    let collided = {
        let mut payload = d43_empty_payload();
        append_d43_mtrr_resource_rows(&mut payload, &[34, 67]);
        append_d43_mtrd_two_way_deals(&mut payload, 34, 67, [0, 0, 0, 0]);
        chunk1_one_snapshot(vec![
            (18, country_identity_payload(&[(34, "SAF"), (67, "ENG")])),
            (43, payload),
        ])
    };
    assert!(
        collided["countries"]["ENG"]["economy"]["resource_trade"]
            .get("deals")
            .is_none(),
        "two rows of one owner sharing a visible_order is a rejected trailer, \
         not a short deal list: {}",
        collided["countries"]["ENG"]["economy"]["resource_trade"]
    );

    // Unique per owner and still not dense: `{0, 2}` apiece. This is the case
    // the uniqueness guard cannot see, so it is what actually pins contiguity,
    // and it is the shape a producer emits if it numbers by ENGINE position and
    // leaves a gap where a route was excluded.
    let gapped = {
        let mut payload = d43_empty_payload();
        append_d43_mtrr_resource_rows(&mut payload, &[34, 67]);
        append_d43_mtrd_two_way_deals(&mut payload, 34, 67, [0, 2, 0, 2]);
        chunk1_one_snapshot(vec![
            (18, country_identity_payload(&[(34, "SAF"), (67, "ENG")])),
            (43, payload),
        ])
    };
    assert!(
        gapped["countries"]["ENG"]["economy"]["resource_trade"]
            .get("deals")
            .is_none(),
        "an owner numbered 0 and 2 is not dense, and the trailer is rejected: {}",
        gapped["countries"]["ENG"]["economy"]["resource_trade"]
    );
}

/// `deals_complete` is a claim the PAYLOAD makes about ONE OWNER, and this is
/// where the fold stops making it on the payload's behalf.
///
/// Before MTRD v3 the projection stamped `deals_complete: true` on every country
/// of any MTRD it accepted. That is why the collector had to withhold the whole
/// family the moment its walk excluded anything: a short list published under
/// an unconditional `true` says the engine DELETED the deals that are missing,
/// and `fold_market_trade` installs the classic families before its own
/// failure-status return, so the `PARTIAL_DATA` badge does not take it back.
///
/// v3 states completeness per owner. SAF is named in the incomplete block, so
/// its rows are published and its claim is `false`; ENG is not, so its claim is
/// `true`. Both owners' rows are on the wire either way -- reciprocity is a
/// property of the DEAL, and dropping an incomplete owner's half would take its
/// exact partner's half down with it and cascade across the trade graph.
///
/// FOUR-FAMILY COHERENCE. The witness list is unchanged by incompleteness: MTRR
/// witnesses `{34, 67}` and so does MTRD, which is what `fold_market_trade`'s
/// country-set equality gate requires. A v3 producer that answered
/// incompleteness by DROPPING the owner would fail that gate and take the whole
/// D43 payload -- MTRF, MTRH, MTRR and MTRD together -- dark. The second half of
/// this test is that gate, driven with a witness genuinely missing.
///
/// What production change makes this fail: restoring the unconditional
/// `json!(true)` in `project_market_trade_classic_deals`, or dropping the
/// incomplete set on the way from the parser into `WorldFold`.
///
/// MUTATION RUN (`--release`): restored
/// `resource_trade.insert("deals_complete".into(), json!(true));`.
/// OBSERVED: FAILED -- "assertion `left == right` failed: SAF is named in the
/// incomplete block, so its list is measured but NOT exhaustive / left: Bool(true)
/// / right: Bool(false)"
///
/// MUTATION RUN (`--release`): made `fold_market_trade` skip the
/// `self.market_trade_classic_deals_incomplete = ...` assignment, i.e. parsed
/// the block and threw it away.
/// OBSERVED: FAILED -- same assertion, same values.
#[test]
fn d43_mtrd_v3_states_completeness_per_owner_not_per_trailer() {
    let snapshot = {
        let mut payload = d43_empty_payload();
        append_d43_mtrr_resource_rows(&mut payload, &[34, 67]);
        append_d43_mtrd_two_way_deals_versioned(
            &mut payload,
            34,
            67,
            [0, 1, 0, 1],
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[34],
        );
        chunk1_one_snapshot(vec![
            (18, country_identity_payload(&[(34, "SAF"), (67, "ENG")])),
            (43, payload),
        ])
    };
    let saf = &snapshot["countries"]["SAF"]["economy"]["resource_trade"];
    let eng = &snapshot["countries"]["ENG"]["economy"]["resource_trade"];
    assert_eq!(
        saf["deals_complete"],
        json!(false),
        "SAF is named in the incomplete block, so its list is measured but NOT \
         exhaustive"
    );
    assert_eq!(
        eng["deals_complete"],
        json!(true),
        "ENG is not named, so its list is exact -- one owner's shortfall must not \
         cost another owner its claim"
    );
    assert_eq!(
        saf["deals"].as_array().map(Vec::len),
        Some(2),
        "and the incomplete owner still publishes every row the recording proved"
    );
    assert_eq!(
        eng["deals"].as_array().map(Vec::len),
        Some(2),
        "with its partner's reciprocal halves intact"
    );

    // The gate a short WITNESS list would hit. MTRR witnesses three countries
    // and this MTRD witnesses two, which is the shape a producer would emit if
    // it answered incompleteness by DROPPING the owner instead of naming it.
    let dropped_witness = {
        let mut payload = d43_empty_payload();
        append_d43_mtrr_resource_rows(&mut payload, &[12, 34, 67]);
        append_d43_mtrd_two_way_deals_versioned(
            &mut payload,
            34,
            67,
            [0, 1, 0, 1],
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[],
        );
        chunk1_one_snapshot(vec![
            (
                18,
                country_identity_payload(&[(12, "FRA"), (34, "SAF"), (67, "ENG")]),
            ),
            (43, payload),
        ])
    };
    assert!(
        dropped_witness["countries"]["ENG"]["economy"]["resource_trade"]
            .get("deals")
            .is_none(),
        "an MTRD that names fewer countries than MTRR takes the WHOLE D43 payload \
         down, which is why per-owner completeness had to keep the witness list \
         whole: {}",
        dropped_witness["countries"]["ENG"]["economy"]["resource_trade"]
    );
}

/// The version word decides the grammar, and every disagreement about it is a
/// refusal rather than a reinterpretation.
///
/// This is the version gate the MTRD bump rests on. The two failure modes it
/// closes:
///
/// * a NEW payload read by an OLD decoder. The pre-v3 whitelist is `{1, 2}` and
///   the pre-v3 rule is "the word at `+0x1C` must be zero", and v3 spends that
///   word on its incomplete count -- so an old decoder refuses a v3 trailer
///   twice over and never reads the completeness block as deal rows. Verified
///   directly against the pre-change parser, out of tree:
///
///   ```text
///   # parse_market_trade_classic_deal_trailer lifted verbatim out of
///   # `git show d16a8484:extractor/native/recorder_host/src/world_fold.rs`
///   # (lines 30407-30593) with its helpers, compiled standalone and driven.
///   v2 (archived shape)        -> Ok, 4 rows over 2 witnesses, end 424
///   v3, no incomplete owners   -> Err("market trade MTRD header shape is invalid")
///   v3, one incomplete owner   -> Err("market trade MTRD header shape is invalid")
///   ```
///
/// * a NEW payload MISLABELLED old, which is the misparse the version word
///   exists to prevent. A v3 body under a `2` puts its incomplete count in a
/// 	 word v2 requires to be zero, so it is refused instead of parsed with the
///   block counted as row bytes.
///
/// What production change makes this fail: widening the version whitelist to
/// accept an unknown version, dropping the reserved-must-be-zero rule for
/// v1/v2, or dropping the ascending-witness-subset rule for the v3 block.
///
/// MUTATION RUN (`--release`): removed `(!per_owner && incomplete_count != 0)`
/// from the header shape check.
/// OBSERVED: FAILED -- "a v3 body labelled v2 must be refused, not parsed with
/// its completeness block counted as row bytes"
///
/// MUTATION RUN (`--release`): removed the `!witnesses.contains(&tag_db_id)`
/// arm of the incomplete-block check.
/// OBSERVED: FAILED -- "an incomplete owner that is not a witness states
/// nothing, and the trailer is refused"
///
/// MUTATION RUN (`--release`): removed the
/// `previous_incomplete.is_some_and(|previous| previous >= tag_db_id)` arm.
/// OBSERVED: FAILED -- "a descending incomplete block is refused: two decoders
/// must not be free to disagree about a set's spelling"
#[test]
fn d43_mtrd_version_word_decides_the_grammar() {
    let fold = |version: u16, incomplete: &[u32]| {
        let mut payload = d43_empty_payload();
        append_d43_mtrr_resource_rows(&mut payload, &[34, 67]);
        append_d43_mtrd_two_way_deals_versioned(
            &mut payload,
            34,
            67,
            [0, 1, 0, 1],
            version,
            incomplete,
        );
        chunk1_one_snapshot(vec![
            (18, country_identity_payload(&[(34, "SAF"), (67, "ENG")])),
            (43, payload),
        ])
    };
    let deals_present = |snapshot: &Value| {
        snapshot["countries"]["ENG"]["economy"]["resource_trade"]
            .get("deals")
            .is_some()
    };

    assert!(
        deals_present(&fold(
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[34]
        )),
        "the control: a well-formed v3 trailer folds"
    );
    assert!(
        deals_present(&fold(MARKET_TRADE_CLASSIC_DEAL_TRAILER_VERSION, &[])),
        "and so does the archived v2 shape, unchanged"
    );

    // A v3 BODY under a v2 label. v2 requires `+0x1C` to be zero, so this is
    // refused rather than parsed with the incomplete block counted as row bytes.
    assert!(
        !deals_present(&fold(MARKET_TRADE_CLASSIC_DEAL_TRAILER_VERSION, &[34])),
        "a v3 body labelled v2 must be refused, not parsed with its completeness \
         block counted as row bytes"
    );
    // An unknown version: refused outright, so a future block cannot be read as
    // rows by a decoder that has never heard of it.
    assert!(
        !deals_present(&fold(
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION + 1,
            &[]
        )),
        "an unknown MTRD version is refused, never guessed at"
    );
    assert!(
        !deals_present(&fold(
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[99]
        )),
        "an incomplete owner that is not a witness states nothing, and the \
         trailer is refused"
    );
    assert!(
        !deals_present(&fold(
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[67, 34]
        )),
        "a descending incomplete block is refused: two decoders must not be free \
         to disagree about a set's spelling"
    );
    assert!(
        !deals_present(&fold(
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[34, 34]
        )),
        "and a repeated one is refused for the same reason"
    );
    assert!(
        !deals_present(&fold(
            MARKET_TRADE_CLASSIC_DEAL_TRAILER_PER_OWNER_VERSION,
            &[34, 67, 67]
        )),
        "an incomplete block longer than the witness list cannot be a subset of it"
    );
}

fn d43_empty_payload() -> Vec<u8> {
    let mut payload = Vec::new();
    payload.extend_from_slice(&0u64.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&0u32.to_le_bytes());
    payload.extend_from_slice(&(FIXED_SCALE as u32).to_le_bytes());
    payload
}

fn d22_state5_payload(owner: u32, controller: u32) -> Vec<u8> {
    let mut payload = Vec::new();
    map_control_header(&mut payload, 1, 1, 0);
    push_state_row(&mut payload, 5, owner, controller);
    push_prov_row(&mut payload, 900, controller, 5);
    payload
}

fn d52_state5_payload() -> Vec<u8> {
    let flags = OCC_ROW_FLAG_RESISTANCE | OCC_ROW_FLAG_COMPLIANCE;
    d52_payload(0, |rows| {
        push_d52_row(rows, 5, 0, 0, 0, 100_000, 200_000, flags);
        1
    })
}

fn assert_state5_chunk1_fields_survive(snap: &Value) {
    assert_eq!(snap["states"]["5"]["owner"], json!("47"));
    assert_eq!(snap["states"]["5"]["controller"], json!("48"));
    assert_eq!(snap["provinces"]["900"]["controller"], json!("48"));
    assert_eq!(snap["provinces"]["900"]["state_id"], json!(5));
    assert_eq!(snap["states"]["5"]["buildings"]["infrastructure"], json!(5));
    assert_eq!(
        snap["states"]["5"]["province_buildings"]["naval_base"],
        json!(10)
    );
    assert!((snap["states"]["5"]["resources"]["steel"].as_f64().unwrap() - 7.0).abs() < 0.0001);
    assert!(
        (snap["states"]["5"]["occupation"]["resistance"]
            .as_f64()
            .unwrap()
            - 1.0)
            .abs()
            < 0.0001
    );
    assert!(
        (snap["states"]["5"]["occupation"]["compliance"]
            .as_f64()
            .unwrap()
            - 2.0)
            .abs()
            < 0.0001
    );
    assert_eq!(snap["map"]["owner_by_state"]["5"], json!("47"));
    assert_eq!(snap["map"]["control_by_province"]["900"], json!("48"));
}

