#[test]
fn chunk2_d20_division_supply_scalars_fold_with_presence() {
    // Div A: supply_gain present-nonzero, disrupted present-nonzero.
    // Div B: supply_gain present-ZERO, disrupted present-ZERO (valid, kept).
    // Div C: both absent (flags clear) -> null, not 0.0.
    let mut divs = Vec::new();
    divisions_header(&mut divs, 3, 0);
    // moving=0, in_combat=0; base_flags carries only the supply/disrupted bits
    // added by the helper.
    push_div_row_with_supply(&mut divs, 17, 0, 118, Some(25_000), Some(39_248));
    push_div_row_with_supply(&mut divs, 18, 0, 119, Some(0), Some(0));
    push_div_row_with_supply(&mut divs, 19, 0, 120, None, None);

    let snap = snapshot_for_domain_records(vec![(20, divs)]);
    let list = snap["divisions"].as_array().unwrap();
    let by_id = |id: u32| {
        list.iter()
            .find(|d| d["div_id"] == json!(id))
            .unwrap_or_else(|| panic!("div {id} missing"))
    };

    let a = by_id(17);
    assert!((a["supply_gain"].as_f64().unwrap() - 0.25).abs() < 1e-9);
    assert!((a["disrupted_supply"].as_f64().unwrap() - 0.39248).abs() < 1e-9);

    let b = by_id(18);
    assert_eq!(b["supply_gain"], json!(0.0));
    assert_eq!(b["disrupted_supply"], json!(0.0));

    let c = by_id(19);
    assert_eq!(c["supply_gain"], Value::Null);
    assert_eq!(c["disrupted_supply"], Value::Null);
}

#[test]
fn chunk2_d20_e4_fields_fold_with_presence() {
    // Div A: all E4 fields present, SR true.
    // Div B: present false/zero values (kept, not null).
    // Div C: all absent -> null.
    let mut divs = Vec::new();
    divisions_header(&mut divs, 3, 0);
    push_div_row_with_e4(&mut divs, 17, Some(true), Some(8777), Some(1234));
    push_div_row_with_e4(&mut divs, 18, Some(false), Some(0), Some(0));
    push_div_row_with_e4(&mut divs, 19, None, None, None);

    let snap = snapshot_for_domain_records(vec![(20, divs)]);
    let list = snap["divisions"].as_array().unwrap();
    let by_id = |id: u32| {
        list.iter()
            .find(|d| d["div_id"] == json!(id))
            .unwrap_or_else(|| panic!("div {id} missing"))
    };

    let a = by_id(17);
    assert_eq!(a["strategic_redeployment"], json!(true));
    assert_eq!(a["current_manpower"], json!(8777));
    assert_eq!(a["cumulative_losses"], json!(1234));

    let b = by_id(18);
    assert_eq!(b["strategic_redeployment"], json!(false));
    assert_eq!(b["current_manpower"], json!(0));
    assert_eq!(b["cumulative_losses"], json!(0));

    let c = by_id(19);
    assert_eq!(c["strategic_redeployment"], Value::Null);
    assert_eq!(c["current_manpower"], Value::Null);
    assert_eq!(c["cumulative_losses"], Value::Null);
}

/// The whole d20 division object, key for key, in three shapes.
///
/// The d20 render moved out of `fold_divisions` into
/// `WorldFold::fold_division_document`, so it is now a function that can be
/// changed on its own. The existing d20 tests each assert one field family and
/// between them leave branches nobody checks: mutation-testing the renderer
/// against the whole suite showed that re-gating `move_progress` on `has_target`
/// instead of `moving`, and collapsing the capped `counter_dig_in_frame` from 2
/// to 1, both pass every other test in the crate.
///
/// So this asserts the COMPLETE object -- all 31 keys -- for a fully observed
/// row, and pins the two tri-state/predicate branches with the rows that
/// distinguish them:
///   A: everything present, moving, dig-in UI visible AND capped  -> frame 2
///   B: NOT moving but a move target present                      -> progress null
///      dig-in UI visible, not capped                             -> frame 1
///   C: nothing observed, dig-in UI evaluated but not visible     -> frame 0
#[test]
fn d20_division_document_renders_every_key_including_the_tri_states() {
    const MOVING: u32 = 1;
    const HAS_TARGET: u32 = 1 << 2;
    const IN_COMBAT: u32 = 1 << 4;
    const HAS_OWNER: u32 = 1 << 5;
    const HAS_ARMY: u32 = 1 << 6;
    const HAS_EXPERIENCE: u32 = 1 << 7;
    const HAS_MAX_SUPPLY: u32 = 1 << 8;
    const HAS_CURRENT_SUPPLY: u32 = 1 << 9;
    const HAS_SUPPLY_GAIN: u32 = 1 << 10;
    const HAS_FUEL: u32 = 1 << 11;
    const ORDER_ARMY: u32 = 1 << 14;
    const ORDER_ARMY_GROUP: u32 = 1 << 15;
    const HAS_DISRUPTED_SUPPLY: u32 = 1 << 17;
    const HAS_COUNTER_SUPPLY_STATUS: u32 = 1 << 22;
    const HAS_DIG_IN: u32 = 1 << 23;
    const HAS_DIG_IN_CAP: u32 = 1 << 24;
    const TRAINING_OBSERVED: u32 = 1 << 25;
    const TRAINING_VISIBLE: u32 = 1 << 26;
    const DIG_IN_UI_OBSERVED: u32 = 1 << 27;
    const DIG_IN_UI_VISIBLE: u32 = 1 << 28;
    const DIG_IN_UI_CAPPED: u32 = 1 << 29;
    const INVALID_ORDERS_OBSERVED: u32 = 1 << 30;
    const INVALID_ORDERS_VISIBLE: u32 = 1 << 31;

    let mut divs = Vec::new();
    divisions_header(&mut divs, 3, 0);
    push_div_row_words(
        &mut divs,
        11,
        &DivRowWords {
            flags: MOVING
                | HAS_TARGET
                | IN_COMBAT
                | HAS_OWNER
                | HAS_ARMY
                | HAS_EXPERIENCE
                | HAS_MAX_SUPPLY
                | HAS_CURRENT_SUPPLY
                | HAS_SUPPLY_GAIN
                | HAS_FUEL
                | DIV_FLAG_TEMPLATE
                | ORDER_ARMY
                | HAS_DISRUPTED_SUPPLY
                | DIV_FLAG_STRATEGIC_REDEPLOYMENT
                | DIV_FLAG_CURRENT_MANPOWER
                | DIV_FLAG_CUMULATIVE_LOSSES
                | DIV_FLAG_MAX_ORGANISATION
                | HAS_COUNTER_SUPPLY_STATUS
                | HAS_DIG_IN
                | HAS_DIG_IN_CAP
                | TRAINING_OBSERVED
                | TRAINING_VISIBLE
                | DIG_IN_UI_OBSERVED
                | DIG_IN_UI_VISIBLE
                | DIG_IN_UI_CAPPED
                | INVALID_ORDERS_OBSERVED
                | INVALID_ORDERS_VISIBLE,
            location: 118,
            move_target: 119,
            movement_progress: 4242,
            organisation_raw: 3_000_000,
            strength_raw: 9_500_000,
            template_id: 77,
            owner: 1,
            army_id: 5,
            experience_raw: 250_000,
            max_supply_raw: 800_000,
            current_supply_raw: 400_000,
            supply_gain_raw: 150_000,
            fuel_raw: 600_000,
            order_instance_id: 909,
            disrupted_supply_raw: 50_000,
            strategic_redeployment_raw: 1,
            current_manpower: 8777,
            cumulative_losses: 1234,
            max_organisation_raw: 6_000_000,
            // Its own bound is 100_000, unlike the other fixed-point fields.
            counter_supply_status_raw: 90_000,
            dig_in_raw: 300_000,
            dig_in_cap_raw: 700_000,
        },
    );
    push_div_row_words(
        &mut divs,
        12,
        &DivRowWords {
            // A move TARGET without MOVING. `move_progress` keys off `moving`.
            flags: HAS_TARGET
                | ORDER_ARMY_GROUP
                | TRAINING_OBSERVED
                | DIG_IN_UI_OBSERVED
                | DIG_IN_UI_VISIBLE,
            location: 200,
            move_target: 201,
            movement_progress: 5555,
            organisation_raw: 1_000_000,
            strength_raw: 2_000_000,
            ..DivRowWords::default()
        },
    );
    push_div_row_words(
        &mut divs,
        13,
        &DivRowWords {
            flags: DIG_IN_UI_OBSERVED,
            location: 300,
            ..DivRowWords::default()
        },
    );

    let snap = snapshot_for_domain_records(vec![
        (18, country_identity_payload(&[(1, "GER")])),
        (20, divs),
    ]);
    let list = snap["divisions"].as_array().expect("divisions array");
    let by_id = |id: u32| {
        list.iter()
            .find(|d| d["div_id"] == json!(id))
            .unwrap_or_else(|| panic!("div {id} missing"))
    };

    // The whole object. Every key the fold publishes is named here, so a key
    // that disappears or gains a sibling fails this rather than going unnoticed.
    assert_eq!(
        *by_id(11),
        json!({
            "div_uid": "11:4713",
            "div_id": 11,
            "div_type": 4713,
            "owner": "GER",
            "location_province": 118,
            "template_id": 77,
            "organisation": 30.0,
            "max_organisation": 60.0,
            "strength": 95.0,
            "moving": true,
            "move_target_province": 119,
            "move_progress": 4242,
            "in_combat": true,
            "experience": 2.5,
            "current_supply": 4.0,
            "max_supply": 8.0,
            "counter_supply_status": 0.9,
            "supply_gain": 1.5,
            "disrupted_supply": 0.5,
            "dig_in": 3.0,
            "dig_in_cap": 7.0,
            "counter_training_visible": true,
            "counter_dig_in_frame": 2,
            "counter_invalid_orders_visible": true,
            "strategic_redeployment": true,
            "current_manpower": 8777,
            "cumulative_losses": 1234,
            "fuel": 6.0,
            "army_id": 5,
            "order_instance_id": 909,
            "order_link": "army",
            // No `equipment`: that key is added later, by `build_divisions`,
            // and only when a d26 record was seen or equipment is retained.
            // This stream carries neither, so the 31 keys above are the whole
            // published object.
        }),
        "the fully observed division, key for key"
    );

    let b = by_id(12);
    assert_eq!(
        b["move_progress"],
        Value::Null,
        "a division with a move target but not moving has no progress"
    );
    assert_eq!(b["move_target_province"], json!(201));
    assert_eq!(b["moving"], json!(false));
    assert_eq!(b["counter_dig_in_frame"], json!(1), "visible, not capped");
    assert_eq!(
        b["counter_training_visible"],
        json!(false),
        "evaluated and not visible is a measured false, not null"
    );
    assert_eq!(b["order_link"], json!("army_group"));
    assert_eq!(b["order_instance_id"], Value::Null);
    assert_eq!(b["owner"], Value::Null);

    let c = by_id(13);
    assert_eq!(c["counter_dig_in_frame"], json!(0), "evaluated, not visible");
    assert_eq!(
        c["counter_training_visible"],
        Value::Null,
        "never evaluated is null, distinct from the measured false above"
    );
    assert_eq!(c["counter_invalid_orders_visible"], Value::Null);
    assert_eq!(c["order_link"], Value::Null);
    for key in [
        "template_id",
        "max_organisation",
        "move_target_province",
        "move_progress",
        "experience",
        "current_supply",
        "max_supply",
        "counter_supply_status",
        "supply_gain",
        "disrupted_supply",
        "dig_in",
        "dig_in_cap",
        "strategic_redeployment",
        "current_manpower",
        "cumulative_losses",
        "fuel",
        "army_id",
        "order_instance_id",
    ] {
        assert_eq!(c[key], Value::Null, "{key} was never observed");
    }
    assert_eq!(c["organisation"], json!(0.0), "always published");
    assert_eq!(c["strength"], json!(0.0), "always published");
    assert_eq!(c["in_combat"], json!(false));
    assert_eq!(c["location_province"], json!(300));
}

#[test]
fn chunk2_d63_country_core_scalars_fold_with_presence() {
    // W1 domain 63: per-country core scalars. Values are the exact D04
    // live-validated readings (see runs/crack_fanout/W1_country_rowgrowth).
    // GER (tag_db_id 1): all fields present. manpower 1640616, convoys 465,
    //   divisions_lost 130; experience raw i32 channels: army raw 901134
    //   (/32768 = 27.50042...), navy raw 13831573 (/32768 = 422.10611...),
    //   air raw 500*32768 = 16384000 (== 500.0), num_armies raw 13815830
    //   (/32768 = 421.62567...). Daily channels set to small raws.
    // SOV (tag_db_id 3): convoys present-zero (a country that has destroyed 0
    //   convoys still folds a present 0), divisions_lost 365, no experience.
    // USA (tag_db_id 68): all absent -> null.
    let ger_exp: [i32; 7] = [
        901_134,    // army   -> 27.50042...
        39_322,     // army_daily -> ~1.20001
        13_831_573, // navy   -> 422.10611...
        3_378,      // navy_daily -> ~0.10306
        16_384_000, // air    -> 500.0
        66_060,     // air_daily -> ~2.01630
        13_815_830, // num_armies_for_training -> 421.62567...
    ];
    let ident = country_identity_payload(&[(1, "GER"), (3, "SOV"), (68, "USA")]);
    let econ = country_core_scalars_payload(&[
        (1, Some(1_640_616), Some(465), Some(130), Some(ger_exp)),
        (3, Some(1_030_000), Some(0), Some(365), None),
        (68, None, None, None, None),
    ]);

    let snap = snapshot_for_domain_records(vec![(18, ident), (63, econ)]);
    let countries = &snap["countries"];

    let ger = &countries["GER"];
    assert_eq!(ger["manpower_pool"], json!(1_640_616));
    assert_eq!(ger["convoys_destroyed"], json!(465));
    assert_eq!(ger["divisions_lost"], json!(130));
    let xp = &ger["experience_status"];
    assert!((xp["army_experience"].as_f64().unwrap() - 27.500_427).abs() < 1e-4);
    assert!((xp["navy_experience"].as_f64().unwrap() - 422.106_11).abs() < 1e-4);
    assert!((xp["air_experience"].as_f64().unwrap() - 500.0).abs() < 1e-9);
    assert!((xp["num_armies_for_training"].as_f64().unwrap() - 421.625_67).abs() < 1e-4);

    let sov = &countries["SOV"];
    assert_eq!(sov["manpower_pool"], json!(1_030_000));
    assert_eq!(sov["convoys_destroyed"], json!(0)); // present zero, not null
    assert_eq!(sov["divisions_lost"], json!(365));
    assert_eq!(sov["experience_status"], Value::Null);

    let usa = &countries["USA"];
    assert_eq!(usa["manpower_pool"], Value::Null);
    assert_eq!(usa["convoys_destroyed"], Value::Null);
    assert_eq!(usa["divisions_lost"], Value::Null);
    assert_eq!(usa["experience_status"], Value::Null);
}

#[test]
fn chunk2_d63_country_core_scalars_rejects_malformed_row() {
    // An experience channel carrying a nonzero value without the experience
    // flag is a malformed row -> the fold fails closed (prior map retained,
    // no country economy fields folded this frame).
    let ident = country_identity_payload(&[(1, "GER")]);
    let mut econ =
        country_core_scalars_payload(&[(1, Some(1_640_616), Some(465), Some(130), None)]);
    // Corrupt: write a nonzero army-experience raw (row offset 20 within the
    // 48-byte row, which starts at payload offset 20) while the experience flag
    // stays clear.
    let army_off = 20 + 20;
    econ[army_off..army_off + 4].copy_from_slice(&999i32.to_le_bytes());

    let snap = snapshot_for_domain_records(vec![(18, ident), (63, econ)]);
    // Fold failed -> GER has no economy fields (the country object may exist
    // from identity but must not carry manpower_pool from the rejected frame).
    let ger = &snap["countries"]["GER"];
    assert!(ger.get("manpower_pool").is_none() || ger["manpower_pool"] == Value::Null);
}

#[test]
fn chunk2_d63_country_core_scalars_refuses_an_hour_whose_rows_miss_a_d18_tag() {
    // The loss the containment gate exists to catch: a D18 tag (SOV) with no
    // d63 row. SOV is a country the snapshot can name, so tolerating the gap
    // would publish the hour as measured while silently omitting its scalars.
    let ident = country_identity_payload(&[(1, "GER"), (3, "SOV")]);
    let econ = country_core_scalars_payload(&[(
        1,
        Some(1_640_616),
        Some(465),
        Some(130),
        None,
    )]);
    let snap = snapshot_for_domain_records(vec![(18, ident), (63, econ)]);
    for tag in ["GER", "SOV"] {
        let country = &snap["countries"][tag];
        assert!(
            country.get("manpower_pool").is_none(),
            "a D63 record missing a D18 tag must not publish a partial roster for {tag}"
        );
    }
    let note = snap["provenance"]["notes"]
        .as_array()
        .unwrap()
        .iter()
        .find_map(|note| {
            let note = note.as_str().unwrap();
            note.contains("domain 63 fold skipped").then(|| note.to_owned())
        })
        .expect("the hour is skipped");
    assert!(
        note.contains("does not cover current-hour D18")
            && note.contains("1 of 2 D18 tags missing")
            && note.contains("d63 carries 1"),
        "{note}"
    );
}

#[test]
fn chunk2_d63_country_core_scalars_validates_atomically_before_mutation() {
    let ident = country_identity_payload(&[(1, "GER"), (3, "SOV")]);
    let mut econ = country_core_scalars_payload(&[
        (1, Some(1_640_616), Some(465), Some(130), None),
        (3, Some(1_030_000), Some(0), Some(365), None),
    ]);
    // Corrupt only the second row after a valid first row. The absent
    // experience flag with a nonzero channel rejects the entire D63 record.
    let second_row = 20 + 48;
    econ[second_row + 20..second_row + 24].copy_from_slice(&999i32.to_le_bytes());
    let snap = snapshot_for_domain_records(vec![(18, ident), (63, econ)]);
    for tag in ["GER", "SOV"] {
        let country = &snap["countries"][tag];
        assert!(
            country.get("manpower_pool").is_none(),
            "late-row corruption must not leave an earlier D63 prefix for {tag}"
        );
    }
}

