#[test]
fn chunk2_d64_del2_projects_all_exact_lifecycle_classes_without_touching_d75() {
    let de = delayed_event_lifecycle_payload(
        &[(1, 100_101, Some(2), Some(7))],
        9,
        &[
            (1, 44, 1, 1, 100_101, 2, 11, 8, Some(7)),
            (2, 45, 2, 1, 100_102, 2, 12, 0, None),
            (3, 45, 3, 1, 100_103, 2, 13, 0, None),
            (4, 45, 4, 1, 100_104, 2, 14, 9, None),
        ],
    );
    let snap = snapshot_for_domain_records(vec![
        (18, country_identity_payload(&[(1, "GER"), (2, "ITA")])),
        (64, de),
    ]);
    let lifecycle = &snap["_r2_delayed_event_lifecycle_live"];
    assert_eq!(lifecycle["hook_epoch"], json!("9"));
    assert_eq!(lifecycle["first_sequence"], json!("1"));
    assert_eq!(lifecycle["last_sequence"], json!("4"));
    assert_eq!(lifecycle["events"][0]["reason"], json!("retained_decrement"));
    assert_eq!(lifecycle["events"][0]["due_after"], json!(7));
    assert_eq!(lifecycle["events"][1]["reason"], json!("executed"));
    assert_eq!(
        lifecycle["events"][2]["reason"],
        json!("failed_trigger_consumed")
    );
    assert_eq!(
        lifecycle["events"][3]["reason"],
        json!("definition_cancelled")
    );
    assert_eq!(lifecycle["events"][0]["originator_tag_db_id"], json!(2));
}

/// Both DEL2 identities are bounded by the ceiling the producing lane applies
/// and the replay consumer re-applies. The fold used to bound only the zero
/// end, so any id up to `u32::MAX` folded through, and replay bounded nothing
/// at all -- the fail-open half of the same drift.
///
/// Pinned absolutely: `100_000` is admitted, `100_001` is not.
#[test]
fn chunk2_d64_del2_identities_stop_at_the_shared_lifecycle_tag_ceiling() {
    assert_eq!(
        portable_admission::MAX_DELAYED_EVENT_LIFECYCLE_TAG_DB_ID,
        100_000
    );
    let ledger = |owner: u32, originator: u32| {
        snapshot_for_domain_records(vec![(
            64,
            delayed_event_lifecycle_payload(
                &[],
                9,
                &[(1, 44, 2, owner, 100_101, originator, 7, 0, None)],
            ),
        )])
    };

    let at_ceiling = ledger(100_000, 100_000);
    assert_eq!(
        at_ceiling["_r2_delayed_event_lifecycle_live"]["events"][0]["owner_tag_db_id"],
        json!(100_000)
    );

    assert_eq!(
        ledger(100_001, 2)["_r2_delayed_event_lifecycle_live"],
        Value::Null
    );
    assert_eq!(
        ledger(2, 100_001)["_r2_delayed_event_lifecycle_live"],
        Value::Null
    );
    assert_eq!(
        ledger(u32::MAX, 2)["_r2_delayed_event_lifecycle_live"],
        Value::Null
    );
}

/// One hour's DEL2 ledger is one drain of the collector's reservable lifecycle
/// queue, so its row count cannot exceed that queue's capacity. The fold
/// applied no count bound and the consumer allowed sixteen times as many.
#[test]
fn chunk2_d64_del2_row_count_stops_at_the_shared_queue_capacity() {
    assert_eq!(portable_admission::MAX_DELAYED_EVENT_LIFECYCLE_EVENTS, 65_536);
    let ledger = |count: u64| {
        snapshot_for_domain_records(vec![(
            64,
            delayed_event_lifecycle_payload(&[], 9, &del2_rows(1, count)),
        )])
    };

    let at_capacity = ledger(portable_admission::MAX_DELAYED_EVENT_LIFECYCLE_EVENTS as u64);
    assert_eq!(
        at_capacity["_r2_delayed_event_lifecycle_live"]["last_sequence"],
        json!("65536")
    );

    assert_eq!(
        ledger(portable_admission::MAX_DELAYED_EVENT_LIFECYCLE_EVENTS as u64 + 1)
            ["_r2_delayed_event_lifecycle_live"],
        Value::Null
    );
}

#[test]
fn chunk2_d64_malformed_first_del2_is_unavailable_not_absent() {
    let mut de = delayed_event_lifecycle_payload(&[], 9, &[]);
    de[30..32].copy_from_slice(&1u16.to_le_bytes());
    let snap = snapshot_for_domain_records(vec![(64, de)]);
    assert_eq!(snap["_r2_delayed_event_lifecycle_live"], Value::Null);
}

// --- d64 DEL2 ledger vs the table-half failure gate ----------------------
//
// The d64 record carries two halves from two producers: the per-country table
// (whose read outcome IS the header status word, `attach_log.rs:61009`-`:61022`)
// and the DEL2 lifecycle trailer, drained from an independent hook whatever the
// table walk did (`:60834`-`:60838`). The trailer is an append-only ledger the
// drain has already consumed, so a frame the fold discards takes real events
// with it and leaves `delayed_event_lifecycle_last_sequence` stale — the next
// clean frame then looks like a sequence gap and permanently poisons the
// history. These tests pin that the two halves settle independently, and that
// the checks which make the ledger trustworthy are NOT weakened by that.

/// One DEL2 row run: `count` consecutive `executed` events from `first`.
fn del2_rows(
    first: u64,
    count: u64,
) -> Vec<(u64, i32, u32, u32, u32, u32, u64, u32, Option<u32>)> {
    (0..count)
        .map(|index| (first + index, 44, 2u32, 1u32, 100_101u32, 2u32, 7u64, 0u32, None))
        .collect()
}

/// Fold `hours` as consecutive game hours — one D18 identity record and one
/// d64 DOMAIN_DATA record each — and return the per-hour snapshots.
fn d64_hourly_snapshots(hours: &[Vec<u8>]) -> Vec<Value> {
    let ident = country_identity_payload(&[(1, "GER"), (2, "ITA")]);
    let mut stream = Vec::new();
    let mut sequence = 1u64;
    for (index, payload) in hours.iter().enumerate() {
        let raw = raw_for(16_959_360 + index as i64);
        for (domain_id, body) in [(18u16, &ident), (64u16, payload)] {
            push_record(
                &mut stream,
                sequence,
                raw,
                domain_id,
                COMPACT_RECORD_TYPE_DOMAIN_DATA,
                body,
            );
            sequence += 1;
        }
        push_record(
            &mut stream,
            sequence,
            raw,
            1000,
            COMPACT_RECORD_TYPE_FRAME_END,
            &frame_end_payload(),
        );
        sequence += 1;
    }
    let mut fold = WorldFold::new("d64_lifecycle_ordering");
    fold.ingest_stream(&stream);
    let snaps = fold.finish();
    assert_eq!(snaps.len(), hours.len());
    snaps.iter().map(|snap| parse(&snap.2)).collect()
}

/// `(first_sequence, last_sequence, event count)` of a published ledger hour,
/// or `None` where the hour published `null` (absent or failed history).
fn del2_published(snapshot: &Value) -> Option<(u64, u64, usize)> {
    let live = &snapshot["_r2_delayed_event_lifecycle_live"];
    if live.is_null() {
        return None;
    }
    Some((
        live["first_sequence"].as_str().unwrap().parse().unwrap(),
        live["last_sequence"].as_str().unwrap().parse().unwrap(),
        live["events"].as_array().unwrap().len(),
    ))
}

#[test]
fn chunk2_d64_failure_status_table_still_settles_its_del2_ledger() {
    // Hour 2's table read failed (SOURCE_UNAVAILABLE — the status every one of
    // the 514 d64 records in runs/batch3/deepwar_a carries). Its trailer is
    // still a drained, contiguous ledger segment and must be published; and
    // because the sequence advanced with it, hours 3 and 4 must stay published
    // too. Returning early on the failure gate loses hour 2's events AND
    // permanently fails the history from hour 3 on.
    let snaps = d64_hourly_snapshots(&[
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(1, 2)),
        delayed_event_lifecycle_payload_with_status(
            &[],
            9,
            &del2_rows(3, 2),
            COMPACT_STATUS_SOURCE_UNAVAILABLE,
        ),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(5, 2)),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(7, 2)),
    ]);
    assert_eq!(del2_published(&snaps[0]), Some((1, 2, 2)));
    assert_eq!(
        del2_published(&snaps[1]),
        Some((3, 4, 2)),
        "a failing table read is no evidence about the hook's drained ledger"
    );
    assert_eq!(
        del2_published(&snaps[2]),
        Some((5, 6, 2)),
        "the failure hour must not leave a stale last_sequence behind it"
    );
    assert_eq!(del2_published(&snaps[3]), Some((7, 8, 2)));
}

#[test]
fn chunk2_d64_failure_status_table_still_retains_the_prior_country_map() {
    // The other half of the same ruling: settling the ledger must not start
    // folding a failing frame's ROWS. Hour 2 badges SOURCE_UNAVAILABLE and
    // carries a row for ITA that the fold must ignore, retaining hour 1's map.
    let snaps = d64_hourly_snapshots(&[
        delayed_events_payload(&[(1, 42_900_001, None, Some(62))]),
        delayed_events_payload_with_status(
            &[(2, 6_700_000, None, Some(2966))],
            COMPACT_STATUS_SOURCE_UNAVAILABLE,
        ),
    ]);
    assert_eq!(
        snaps[1]["countries"]["GER"]["delayed_events"][0]["event_id"],
        json!(42_900_001),
        "a failure-status frame must not clear the retained map"
    );
    let ita = &snaps[1]["countries"]["ITA"];
    assert!(
        ita.get("delayed_events").is_none() || ita["delayed_events"] == json!([]),
        "a failure-status frame's rows must not be folded"
    );
}

#[test]
fn chunk2_d64_absent_trailer_on_a_failure_frame_is_not_a_ledger_hole() {
    // A failing read either returns before the drain
    // (`attach_log.rs:60815`-`:60824`) or never reaches it, so the queued
    // events are still queued: hour 2 carrying no trailer is not a hole, and
    // hour 3's contiguous segment must still publish.
    let snaps = d64_hourly_snapshots(&[
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(1, 2)),
        delayed_events_payload_with_status(&[], COMPACT_STATUS_SOURCE_UNAVAILABLE),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(3, 2)),
    ]);
    assert_eq!(del2_published(&snaps[0]), Some((1, 2, 2)));
    assert_eq!(del2_published(&snaps[1]), None);
    assert_eq!(
        del2_published(&snaps[2]),
        Some((3, 4, 2)),
        "a failure frame that never drained must not fail the history"
    );
}

#[test]
fn chunk2_d64_absent_trailer_on_a_clean_frame_is_still_a_ledger_hole() {
    // The converse, unchanged: the table read succeeded, so the trailer is
    // missing because the hook is gone or its drain failed. Those events are
    // lost, and the history stays failed for every later hour.
    let snaps = d64_hourly_snapshots(&[
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(1, 2)),
        delayed_events_payload(&[]),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(3, 2)),
    ]);
    assert_eq!(del2_published(&snaps[0]), Some((1, 2, 2)));
    assert_eq!(del2_published(&snaps[1]), None);
    assert_eq!(
        del2_published(&snaps[2]),
        None,
        "a proven hole must fail the history permanently"
    );
}

#[test]
fn chunk2_d64_a_malformed_row_does_not_consume_the_del2_trailer() {
    // Same property one layer down: a zero event_id fails the TABLE half, and
    // is no more evidence about the trailer than a failure status is. Hour 2
    // publishes its ledger and retains hour 1's map; hour 3 stays published.
    let snaps = d64_hourly_snapshots(&[
        delayed_event_lifecycle_payload(&[(1, 42_900_001, None, Some(62))], 9, &del2_rows(1, 2)),
        delayed_event_lifecycle_payload(&[(1, 0, None, Some(62))], 9, &del2_rows(3, 2)),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(5, 2)),
    ]);
    assert_eq!(del2_published(&snaps[0]), Some((1, 2, 2)));
    assert_eq!(
        del2_published(&snaps[1]),
        Some((3, 4, 2)),
        "a malformed row must not throw the drained ledger away"
    );
    assert_eq!(
        snaps[1]["countries"]["GER"]["delayed_events"][0]["event_id"],
        json!(42_900_001),
        "the table half still fails closed on a malformed row"
    );
    assert_eq!(del2_published(&snaps[2]), Some((5, 6, 2)));
}

#[test]
fn chunk2_d64_a_real_sequence_gap_still_fails_the_history_permanently() {
    // Settling on more frames must not weaken what makes the ledger
    // trustworthy: a genuine discontinuity (3 and 4 never arrived) is still
    // fatal, on that hour and every hour after it.
    let snaps = d64_hourly_snapshots(&[
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(1, 2)),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(5, 2)),
        delayed_event_lifecycle_payload(&[], 9, &del2_rows(7, 2)),
    ]);
    assert_eq!(del2_published(&snaps[0]), Some((1, 2, 2)));
    assert_eq!(del2_published(&snaps[1]), None);
    assert_eq!(del2_published(&snaps[2]), None);
}

#[test]
fn chunk2_d67_country_dynamic_modifiers_fold_melt_anchored() {
    // W5 domain 67: per-country OWN dynamic-modifier id SET. Melt-anchored (D04
    // multiset counts, agent D2): GER 9, USA 1 (ABDA_supreme_command), ITA 5.
    // ENG is identity-only (no modifier row) -> empty list (absent == none).
    let ident = country_identity_payload(&[(1, "GER"), (68, "USA"), (16, "ITA"), (3, "ENG")]);
    let ger_ids: Vec<String> = (0..9).map(|i| format!("GER_dm_{i}")).collect();
    let ita_ids: Vec<String> = (0..5).map(|i| format!("ITA_dm_{i}")).collect();
    let ger_refs: Vec<&str> = ger_ids.iter().map(String::as_str).collect();
    let ita_refs: Vec<&str> = ita_ids.iter().map(String::as_str).collect();
    let dm = country_dynamic_modifiers_payload(
        &[
            (1, &ger_refs),
            (68, &["ABDA_supreme_command"]),
            (16, &ita_refs),
        ],
        0,
    );

    let snap = snapshot_for_domain_records(vec![(18, ident), (67, dm)]);
    let countries = &snap["countries"];

    // GER: 9 modifiers, sorted for a stable multiset.
    let ger = &countries["GER"]["dynamic_modifier"];
    assert_eq!(ger.as_array().unwrap().len(), 9);
    let mut expected = ger_ids.clone();
    expected.sort();
    let got: Vec<String> = ger
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    assert_eq!(got, expected);

    // USA: exactly one, the shared/interned ABDA_supreme_command def.
    let usa = &countries["USA"]["dynamic_modifier"];
    assert_eq!(usa.as_array().unwrap().len(), 1);
    assert_eq!(usa[0], json!("ABDA_supreme_command"));

    // ITA: 5 modifiers.
    let ita = &countries["ITA"]["dynamic_modifier"];
    assert_eq!(ita.as_array().unwrap().len(), 5);

    // ENG: identity-only -> empty list (full-replace cleared it, no row set it).
    let eng = &countries["ENG"];
    assert!(eng.get("dynamic_modifier").is_none() || eng["dynamic_modifier"] == json!([]));
}

#[test]
fn chunk2_d67_country_dynamic_modifiers_full_replace_clears_stale() {
    // Full-replace: a country that HAD a modifier in frame 1 and NONE in frame 2
    // must show an empty list in frame 2, never a stale modifier.
    let mut stream = Vec::new();
    let mut seq = 1u64;
    // Frame 1: GER has one modifier.
    let raw1 = raw_for(16_959_360);
    push_record(
        &mut stream,
        seq,
        raw1,
        18,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_identity_payload(&[(1, "GER"), (68, "USA")]),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw1,
        67,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_dynamic_modifiers_payload(&[(1, &["GER_army_modifier"])], 0),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw1,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );
    seq += 1;
    // Frame 2 (advance one hour): GER's modifier expired -> no GER row; USA now
    // carries one. The frame is non-empty (USA present) so it is not treated as
    // an all-absent source-unavailable frame; GER's list must be cleared.
    let raw2 = raw_for(16_959_360 + 1);
    push_record(
        &mut stream,
        seq,
        raw2,
        18,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_identity_payload(&[(1, "GER"), (68, "USA")]),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw2,
        67,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_dynamic_modifiers_payload(&[(68, &["USA_focus_modifier"])], 0),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw2,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );

    let mut fold = WorldFold::new("d67_full_replace");
    fold.ingest_stream(&stream);
    let snaps = fold.finish();
    assert_eq!(snaps.len(), 2);
    let frame1 = parse(&snaps[0].2);
    let frame2 = parse(&snaps[1].2);
    // Frame 1: GER has its modifier.
    assert_eq!(
        frame1["countries"]["GER"]["dynamic_modifier"][0],
        json!("GER_army_modifier")
    );
    // Frame 2: full-replace cleared GER's stale modifier -> empty list; USA set.
    assert_eq!(frame2["countries"]["GER"]["dynamic_modifier"], json!([]));
    assert_eq!(
        frame2["countries"]["USA"]["dynamic_modifier"][0],
        json!("USA_focus_modifier")
    );
}

#[test]
fn chunk2_d67_country_dynamic_modifiers_rejects_truncated_blob() {
    // A row claiming more ids than the blob supplies is a torn payload -> the
    // fold fails closed (no dynamic_modifier field folded this frame).
    let ident = country_identity_payload(&[(1, "GER")]);
    let mut dm = country_dynamic_modifiers_payload(&[(1, &["GER_army_modifier"])], 0);
    // Corrupt the row's id_count (row table starts at 20; id_count is at +4).
    let id_count_off = 20 + 4;
    dm[id_count_off..id_count_off + 4].copy_from_slice(&5u32.to_le_bytes());
    let snap = snapshot_for_domain_records(vec![(18, ident), (67, dm)]);
    let ger = &snap["countries"]["GER"];
    assert!(ger.get("dynamic_modifier").is_none() || ger["dynamic_modifier"] == Value::Null);
}

#[test]
fn chunk2_d67_country_dynamic_modifiers_rejects_noncontiguous_window() {
    // A row whose id_blob_offset skips ids (a hole) or overlaps another row is a
    // crafted/torn payload -> fold fails closed. Build a valid 2-country payload
    // then corrupt the SECOND row's id_blob_offset so it points back at 0
    // (overlap) instead of the expected running cursor.
    let ident = country_identity_payload(&[(1, "GER"), (68, "USA")]);
    let mut dm = country_dynamic_modifiers_payload(
        &[(1, &["GER_army_modifier"]), (68, &["USA_focus_modifier"])],
        0,
    );
    // Row 1 (USA) starts at header(20) + one 12-byte row = 32; its
    // id_blob_offset is at +8 within that row.
    let usa_offset_field = 20 + COUNTRY_DYNAMIC_MODIFIERS_ROW_LEN + 8;
    dm[usa_offset_field..usa_offset_field + 4].copy_from_slice(&0u32.to_le_bytes());
    let snap = snapshot_for_domain_records(vec![(18, ident), (67, dm)]);
    // Fold rejected the whole frame -> neither country carries a folded list.
    let ger = &snap["countries"]["GER"];
    assert!(ger.get("dynamic_modifier").is_none() || ger["dynamic_modifier"] == Value::Null);
}

#[test]
fn chunk2_d67_country_dynamic_modifiers_empty_frame_clears_all() {
    // Q4 fail-closed correctness: a SUCCESSFUL frame in which zero countries
    // carry a modifier (country_count==0, clean status) must CLEAR every known
    // country's list, not retain a stale set. Frame 1 sets GER; frame 2 is an
    // empty (0-row) successful frame -> GER's list must become empty.
    let mut stream = Vec::new();
    let mut seq = 1u64;
    let raw1 = raw_for(16_959_360);
    push_record(
        &mut stream,
        seq,
        raw1,
        18,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_identity_payload(&[(1, "GER")]),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw1,
        67,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_dynamic_modifiers_payload(&[(1, &["GER_army_modifier"])], 0),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw1,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );
    seq += 1;
    // Frame 2: empty successful d67 frame (no rows, clean status).
    let raw2 = raw_for(16_959_360 + 1);
    push_record(
        &mut stream,
        seq,
        raw2,
        18,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_identity_payload(&[(1, "GER")]),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw2,
        67,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_dynamic_modifiers_payload(&[], 0),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw2,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );

    let mut fold = WorldFold::new("d67_empty_clears");
    fold.ingest_stream(&stream);
    let snaps = fold.finish();
    assert_eq!(snaps.len(), 2);
    let frame2 = parse(&snaps[1].2);
    assert_eq!(
        frame2["countries"]["GER"]["dynamic_modifier"],
        json!([]),
        "an empty successful frame must clear the stale set, not retain it"
    );
}

#[test]
fn chunk2_d67_country_dynamic_modifiers_partial_data_retains_prior() {
    // Q2/Q4 fail-closed: when the collector marks the frame torn (PARTIAL_DATA,
    // which is NOT an expected-partial tolerance for d67), the fold must RETAIN
    // the prior per-country set rather than publish a truncated set or clear it.
    // Frame 1 sets GER; frame 2 carries PARTIAL_DATA -> GER's set is retained.
    let mut stream = Vec::new();
    let mut seq = 1u64;
    let raw1 = raw_for(16_959_360);
    push_record(
        &mut stream,
        seq,
        raw1,
        18,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_identity_payload(&[(1, "GER")]),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw1,
        67,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_dynamic_modifiers_payload(&[(1, &["GER_army_modifier"])], 0),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw1,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );
    seq += 1;
    // Frame 2: a torn (PARTIAL_DATA) d67 frame with no rows. The prior GER set
    // must survive (the collector drops rows on torn and sets PARTIAL_DATA).
    let raw2 = raw_for(16_959_360 + 1);
    push_record(
        &mut stream,
        seq,
        raw2,
        18,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_identity_payload(&[(1, "GER")]),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw2,
        67,
        COMPACT_RECORD_TYPE_DOMAIN_DATA,
        &country_dynamic_modifiers_payload(&[], COMPACT_STATUS_PARTIAL_DATA),
    );
    seq += 1;
    push_record(
        &mut stream,
        seq,
        raw2,
        1000,
        COMPACT_RECORD_TYPE_FRAME_END,
        &frame_end_payload(),
    );

    let mut fold = WorldFold::new("d67_partial_retains");
    fold.ingest_stream(&stream);
    let snaps = fold.finish();
    assert_eq!(snaps.len(), 2);
    let frame2 = parse(&snaps[1].2);
    assert_eq!(
        frame2["countries"]["GER"]["dynamic_modifier"][0],
        json!("GER_army_modifier"),
        "a torn (PARTIAL_DATA) frame must retain the prior set, not clear it"
    );
}

#[test]
fn a18_d67_v2_preserves_exact_instance_fields_and_measured_zero() {
    let ident = country_identity_payload(&[(33, "AST")]);
    let payload = country_dynamic_modifier_instances_payload(
        &[(
            33,
            "AST_eminent_successors_spirit",
            true,
            &[15_000, -10_000, 0],
            Some(0),
        )],
        0,
    );
    let snap = snapshot_for_domain_records_with_flags(vec![
        (18, ident, 0),
        (
            67,
            payload,
            compact_contract::COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
        ),
    ]);
    let row = &snap["countries"]["AST"]["dynamic_modifier_instances"][0];
    assert_eq!(row["modifier"], json!("AST_eminent_successors_spirit"));
    assert_eq!(row["enabled"], json!(true));
    assert_eq!(row["values_raw"], json!([15_000, -10_000, 0]));
    assert_eq!(row["value_scale"], json!(100_000));
    assert_eq!(row["remaining_days"], json!(0));
    assert_eq!(
        snap["_r2_dynamic_modifier_lifecycle_live"]["source_binary_sha256"],
        json!("870ebf1f615262facca48a3b947775c41f0a5338f3068c40958209f5c41c65ad")
    );
    assert_eq!(
        snap["_r2_dynamic_modifier_lifecycle_live"]["static_authority_receipt_sha256"],
        json!("bdbac3cb1158c971b408586611d6aba618ecfe85b5265e3b9e8c2c0bf545e415")
    );
    assert_eq!(
        snap["_r2_dynamic_modifier_lifecycle_live"]["transitions"][0]["owner_tag"],
        json!("AST")
    );
    assert!(
        snap["_r2_dynamic_modifier_lifecycle_live"]
            .get("absolute_expiry_hour")
            .is_none(),
        "the fold must never emit an expiry hour from remaining days"
    );
}

#[test]
fn a18_d67_v2_only_classifies_removal_after_observed_zero() {
    let mut stream = Vec::new();
    let mut sequence = 1u64;
    for (offset, days, present) in [(0, Some(1), true), (1, Some(0), true), (2, None, false)] {
        let raw = raw_for(16_959_360 + offset);
        push_record(
            &mut stream,
            sequence,
            raw,
            18,
            COMPACT_RECORD_TYPE_DOMAIN_DATA,
            &country_identity_payload(&[(33, "AST")]),
        );
        sequence += 1;
        let rows = if present {
            vec![(
                33,
                "AST_eminent_successors_spirit",
                true,
                Vec::<i64>::new(),
                days,
            )]
        } else {
            Vec::new()
        };
        let borrowed = rows
            .iter()
            .map(|(owner, modifier, enabled, values, remaining)| {
                (*owner, *modifier, *enabled, values.as_slice(), *remaining)
            })
            .collect::<Vec<_>>();
        push_record_with_flags(
            &mut stream,
            sequence,
            raw,
            67,
            COMPACT_RECORD_TYPE_DOMAIN_DATA,
            compact_contract::COMPACT_RECORD_FLAG_PAYLOAD_SCHEMA_V2,
            &country_dynamic_modifier_instances_payload(&borrowed, 0),
        );
        sequence += 1;
        push_record(
            &mut stream,
            sequence,
            raw,
            1000,
            COMPACT_RECORD_TYPE_FRAME_END,
            &frame_end_payload(),
        );
        sequence += 1;
    }
    let mut fold = WorldFold::new("a18_zero_removal");
    fold.ingest_stream(&stream);
    let snapshots = fold.finish();
    let zero = parse(&snapshots[1].2);
    let removed = parse(&snapshots[2].2);
    assert_eq!(
        zero["_r2_dynamic_modifier_lifecycle_live"]["transitions"][0]["kind"],
        json!("zero_observed")
    );
    assert_eq!(
        removed["_r2_dynamic_modifier_lifecycle_live"]["transitions"][0]
            ["expiry_classification"],
        json!("removed_after_observed_zero")
    );
    assert_eq!(
        removed["countries"]["AST"]["dynamic_modifier_instances"],
        json!([])
    );
}

