    assert_eq!(authority.data_units["deployment_queue_conveyor_rows"], 1);
    assert_eq!(authority.data_units["deployment_queue_line_rows"], 1);
    assert_eq!(authority.data_units["deployment_queue_equipment_rows"], 1);
